class StreamTriggerTaskTest : public ::testing::Test {
 protected:
  void SetUp() override {
    // Test setup
    // Use Asia/Shanghai timezone for consistent testing
    taosSetGlobalTimezone("Asia/Shanghai");
  }

  void TearDown() override {
    // Test cleanup
  }

  /**
   * Helper function to convert human-readable datetime to timestamp
   * @param year Year (e.g., 2026)
   * @param month Month (1-12)
   * @param day Day (1-31)
   * @param hour Hour (0-23)
   * @param minute Minute (0-59)
   * @param second Second (0-59)
   * @param precision Time precision (TSDB_TIME_PRECISION_MILLI/MICRO/NANO)
   * @return Timestamp in specified precision
   */
  int64_t makeTimestamp(int year, int month, int day, int hour, int minute, int second,
                        int8_t precision = TSDB_TIME_PRECISION_MILLI) {
    struct tm tm = {0};
    tm.tm_year = year - 1900;
    tm.tm_mon = month - 1;
    tm.tm_mday = day;
    tm.tm_hour = hour;
    tm.tm_min = minute;
    tm.tm_sec = second;
    tm.tm_isdst = -1;

    time_t  t = taosMktime(&tm, NULL);
    int64_t ts = (int64_t)t;

    switch (precision) {
      case TSDB_TIME_PRECISION_MILLI:
        return ts * 1000LL;
      case TSDB_TIME_PRECISION_MICRO:
        return ts * 1000000LL;
      case TSDB_TIME_PRECISION_NANO:
        return ts * 1000000000LL;
      default:
        return ts * 1000LL;
    }
  }

  /**
   * Helper function to verify window boundaries
   * @param win Window to verify
   * @param precision Time precision
   * @param skeyYear Expected skey year (e.g., 2026), -1 to skip
   * @param skeyMonth Expected skey month (1-12), -1 to skip
   * @param skeyDay Expected skey day (1-31), -1 to skip
   * @param skeyHour Expected skey hour (0-23), -1 to skip
   * @param skeyMin Expected skey minute (0-59), -1 to skip
   * @param skeySec Expected skey second (0-59), -1 to skip
   * @param skeyWday Expected skey day of week (0-6, 0=Sunday), -1 to skip
   * @param ekeyYear Expected ekey year (e.g., 2026), -1 to skip
   * @param ekeyMonth Expected ekey month (1-12), -1 to skip
   * @param ekeyDay Expected ekey day (1-31), -1 to skip
   * @param ekeyHour Expected ekey hour (0-23), -1 to skip
   * @param ekeyMin Expected ekey minute (0-59), -1 to skip
   * @param ekeySec Expected ekey second (0-59), -1 to skip
   * @param ekeyWday Expected ekey day of week (0-6, 0=Sunday), -1 to skip
   * @param expectedDurationMs Expected duration in milliseconds (closed interval), -1 to skip
   */
  void verifyWindow(const STimeWindow& win, int8_t precision, int skeyYear = -1, int skeyMonth = -1, int skeyDay = -1,
                    int skeyHour = -1, int skeyMin = -1, int skeySec = -1, int skeyWday = -1, int ekeyYear = -1,
                    int ekeyMonth = -1, int ekeyDay = -1, int ekeyHour = -1, int ekeyMin = -1, int ekeySec = -1,
                    int ekeyWday = -1, int64_t expectedDurationMs = -1) {
    // Convert precision factor
    int64_t precisionFactor = 1;
    switch (precision) {
      case TSDB_TIME_PRECISION_MILLI:
        precisionFactor = 1000LL;
        break;
      case TSDB_TIME_PRECISION_MICRO:
        precisionFactor = 1000000LL;
        break;
      case TSDB_TIME_PRECISION_NANO:
        precisionFactor = 1000000000LL;
        break;
    }

    // Verify skey
    time_t    t_skey = win.skey / precisionFactor;
    struct tm tm_skey;
    taosLocalTime(&t_skey, &tm_skey, NULL, 0, NULL);

    if (skeyYear >= 0) EXPECT_EQ(tm_skey.tm_year, skeyYear - 1900);
    if (skeyMonth >= 0) EXPECT_EQ(tm_skey.tm_mon, skeyMonth - 1);
    if (skeyDay >= 0) EXPECT_EQ(tm_skey.tm_mday, skeyDay);
    if (skeyHour >= 0) EXPECT_EQ(tm_skey.tm_hour, skeyHour);
    if (skeyMin >= 0) EXPECT_EQ(tm_skey.tm_min, skeyMin);
    if (skeySec >= 0) EXPECT_EQ(tm_skey.tm_sec, skeySec);
    if (skeyWday >= 0) EXPECT_EQ(tm_skey.tm_wday, skeyWday);

    // Verify ekey
    time_t    t_ekey = win.ekey / precisionFactor;
    struct tm tm_ekey;
    taosLocalTime(&t_ekey, &tm_ekey, NULL, 0, NULL);

    if (ekeyYear >= 0) EXPECT_EQ(tm_ekey.tm_year, ekeyYear - 1900);
    if (ekeyMonth >= 0) EXPECT_EQ(tm_ekey.tm_mon, ekeyMonth - 1);
    if (ekeyDay >= 0) EXPECT_EQ(tm_ekey.tm_mday, ekeyDay);
    if (ekeyHour >= 0) EXPECT_EQ(tm_ekey.tm_hour, ekeyHour);
    if (ekeyMin >= 0) EXPECT_EQ(tm_ekey.tm_min, ekeyMin);
    if (ekeySec >= 0) EXPECT_EQ(tm_ekey.tm_sec, ekeySec);
    if (ekeyWday >= 0) EXPECT_EQ(tm_ekey.tm_wday, ekeyWday);

    // Verify duration (closed interval: ekey - skey + 1)
    if (expectedDurationMs >= 0) {
      int64_t duration = win.ekey - win.skey + 1;
      int64_t expectedDuration = expectedDurationMs * (precisionFactor / 1000LL);
      EXPECT_EQ(duration, expectedDuration);
    }
  }
};

class StreamNestedRealtimeTest : public StreamTriggerTaskTest {};

static SStreamNestedPendingCalcEvent makeNestedPendingEvent() {
  SStreamNestedPendingCalcEvent event = {};
  event.calcParam.wstart = 100;
  event.calcParam.wend = 199;
  event.calcParam.wduration = 99;
  event.calcParam.wrownum = 2;
  event.calcParam.triggerTime = 123456;
  event.calcParam.notifyType = STRIGGER_EVENT_WINDOW_CLOSE;
  event.calcParam.extraNotifyContent = taosStrdup("{\"detail\":1}");
  event.contextPolicy = STREAM_CONTEXT_POLICY_ANCESTOR;
  event.leafIdentity.gid = 42;
  event.leafIdentity.triggerType = WINDOW_TYPE_COUNT;
  event.leafIdentity.openingTs = 100;
  event.leafIdentity.nativeDiscriminator = 7;
  event.leafIdentity.lineage.pScopes = taosArrayInit(2, sizeof(SScopeInstanceId));
  if (event.leafIdentity.lineage.pScopes != nullptr) {
    const SScopeInstanceId root = {
        .layerIndex = 0, .triggerType = WINDOW_TYPE_INTERVAL, .openingTs = 1, .nativeDiscriminator = 3};
    const SScopeInstanceId parent = {
        .layerIndex = 1, .triggerType = WINDOW_TYPE_SESSION, .openingTs = 90, .nativeDiscriminator = 4};
    (void)taosArrayPush(event.leafIdentity.lineage.pScopes, &root);
    (void)taosArrayPush(event.leafIdentity.lineage.pScopes, &parent);
  }
  event.pSnapshots = taosArrayInit(2, sizeof(SWindowAncestorSnapshot));
  if (event.pSnapshots != nullptr) {
    const SWindowAncestorSnapshot root = {
        .layerIndex = 0,
        .triggerType = WINDOW_TYPE_INTERVAL,
        .placeholderMask = PLACE_HOLDER_PREV_TS | PLACE_HOLDER_CURRENT_TS | PLACE_HOLDER_NEXT_TS,
        .values = {.sliding = {.prevTs = 1, .currentTs = 1000, .nextTs = 2000}},
    };
    const SWindowAncestorSnapshot parent = {
        .layerIndex = 1,
        .triggerType = WINDOW_TYPE_SESSION,
        .placeholderMask = PLACE_HOLDER_WSTART | PLACE_HOLDER_WEND | PLACE_HOLDER_WDURATION | PLACE_HOLDER_WROWNUM,
        .values = {.window = {.start = 90, .end = 199, .duration = 110, .rownum = 2}},
    };
    (void)taosArrayPush(event.pSnapshots, &root);
    (void)taosArrayPush(event.pSnapshots, &parent);
  }
  return event;
}

static void destroyNestedPendingEventSource(SStreamNestedPendingCalcEvent* pEvent) {
  taosArrayDestroy(pEvent->leafIdentity.lineage.pScopes);
  pEvent->leafIdentity.lineage.pScopes = nullptr;
  taosArrayDestroy(pEvent->pSnapshots);
  pEvent->pSnapshots = nullptr;
  tDestroySSTriggerCalcParam(&pEvent->calcParam);
}

static constexpr std::array<uint8_t, DECIMAL128_BYTES> kNestedDecimalBytes = {
    0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff};

static void populateNestedPendingCalcOwnedFields(SStreamNestedPendingCalcEvent* pEvent) {
  pEvent->calcParam.resultNotifyContent = taosStrdup("{\"result\":2}");
  ASSERT_NE(nullptr, pEvent->calcParam.resultNotifyContent);
  pEvent->calcParam.pExternalWindowData = taosArrayInit(3, sizeof(SStreamGroupValue));
  ASSERT_NE(nullptr, pEvent->calcParam.pExternalWindowData);

  SStreamGroupValue fixed = {};
  fixed.data.type = TSDB_DATA_TYPE_BIGINT;
  fixed.data.val = 1234;
  fixed.uid = 11;
  fixed.vgId = 12;
  ASSERT_NE(nullptr, taosArrayPush(pEvent->calcParam.pExternalWindowData, &fixed));

  SStreamGroupValue variable = {};
  variable.data.type = TSDB_DATA_TYPE_BINARY;
  variable.data.nData = 5;
  variable.data.pData = static_cast<uint8_t*>(taosMemoryMalloc(variable.data.nData));
  ASSERT_NE(nullptr, variable.data.pData);
  memcpy(variable.data.pData, "owned", variable.data.nData);
  variable.uid = 21;
  variable.vgId = 22;
  ASSERT_NE(nullptr, taosArrayPush(pEvent->calcParam.pExternalWindowData, &variable));

  SStreamGroupValue decimal = {};
  decimal.data.type = TSDB_DATA_TYPE_DECIMAL;
  decimal.data.nData = DECIMAL128_BYTES;
  decimal.data.pData = static_cast<uint8_t*>(taosMemoryMalloc(decimal.data.nData));
  ASSERT_NE(nullptr, decimal.data.pData);
  memcpy(decimal.data.pData, kNestedDecimalBytes.data(), decimal.data.nData);
  decimal.uid = 31;
  decimal.vgId = 32;
  ASSERT_NE(nullptr, taosArrayPush(pEvent->calcParam.pExternalWindowData, &decimal));
}

static int32_t countJsonMembersNamed(const cJSON* pObject, const char* pName) {
  int32_t count = 0;
  if (!cJSON_IsObject(pObject) || pName == nullptr) return count;
  for (const cJSON* pItem = pObject->child; pItem != nullptr; pItem = pItem->next) {
    if (pItem->string != nullptr && strcmp(pItem->string, pName) == 0) ++count;
  }
  return count;
}

static cJSON* nestedNoticeEvent(cJSON* pRoot) {
  cJSON* pStreams = cJSON_GetObjectItemCaseSensitive(pRoot, "streams");
  if (!cJSON_IsArray(pStreams)) return nullptr;
  cJSON* pStream = cJSON_GetArrayItem(pStreams, 0);
  if (!cJSON_IsObject(pStream)) return nullptr;
  cJSON* pEvents = cJSON_GetObjectItemCaseSensitive(pStream, "events");
  if (!cJSON_IsArray(pEvents)) return nullptr;
  cJSON* pEvent = cJSON_GetArrayItem(pEvents, 0);
  return cJSON_IsObject(pEvent) ? pEvent : nullptr;
}

