TEST_F(StreamNestedRealtimeTest, PendingEventDeepClonesEveryCalcOwnedField) {
  SStreamNestedPendingCalcEvent source = makeNestedPendingEvent();
  populateNestedPendingCalcOwnedFields(&source);
  ASSERT_NE(nullptr, source.calcParam.resultNotifyContent);
  ASSERT_NE(nullptr, source.calcParam.pExternalWindowData);
  ASSERT_EQ(3, taosArrayGetSize(source.calcParam.pExternalWindowData));

  SListNode* node = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stAllocNestedPendingCalcNode(&source, &node));
  ASSERT_NE(nullptr, node);
  const auto* owned = reinterpret_cast<const SStreamNestedPendingCalcEvent*>(node->data);
  ASSERT_NE(nullptr, owned->calcParam.resultNotifyContent);
  ASSERT_NE(nullptr, owned->calcParam.pExternalWindowData);
  EXPECT_NE(source.calcParam.resultNotifyContent, owned->calcParam.resultNotifyContent);
  EXPECT_NE(source.calcParam.pExternalWindowData, owned->calcParam.pExternalWindowData);
  EXPECT_STREQ("{\"result\":2}", owned->calcParam.resultNotifyContent);
  ASSERT_EQ(3, taosArrayGetSize(owned->calcParam.pExternalWindowData));

  auto*       sourceFixed = static_cast<SStreamGroupValue*>(taosArrayGet(source.calcParam.pExternalWindowData, 0));
  auto*       sourceVariable = static_cast<SStreamGroupValue*>(taosArrayGet(source.calcParam.pExternalWindowData, 1));
  auto*       sourceDecimal = static_cast<SStreamGroupValue*>(taosArrayGet(source.calcParam.pExternalWindowData, 2));
  const auto* ownedFixed = static_cast<const SStreamGroupValue*>(taosArrayGet(owned->calcParam.pExternalWindowData, 0));
  const auto* ownedVariable =
      static_cast<const SStreamGroupValue*>(taosArrayGet(owned->calcParam.pExternalWindowData, 1));
  const auto* ownedDecimal =
      static_cast<const SStreamGroupValue*>(taosArrayGet(owned->calcParam.pExternalWindowData, 2));
  ASSERT_NE(nullptr, sourceFixed);
  ASSERT_NE(nullptr, sourceVariable);
  ASSERT_NE(nullptr, sourceDecimal);
  ASSERT_NE(nullptr, ownedFixed);
  ASSERT_NE(nullptr, ownedVariable);
  ASSERT_NE(nullptr, ownedDecimal);
  EXPECT_EQ(TSDB_DATA_TYPE_BIGINT, ownedFixed->data.type);
  EXPECT_EQ(1234, ownedFixed->data.val);
  EXPECT_EQ(11, ownedFixed->uid);
  EXPECT_EQ(12, ownedFixed->vgId);
  EXPECT_EQ(TSDB_DATA_TYPE_BINARY, ownedVariable->data.type);
  EXPECT_EQ(5U, ownedVariable->data.nData);
  EXPECT_EQ(21, ownedVariable->uid);
  EXPECT_EQ(22, ownedVariable->vgId);
  ASSERT_NE(nullptr, sourceVariable->data.pData);
  ASSERT_NE(nullptr, ownedVariable->data.pData);
  EXPECT_NE(sourceVariable->data.pData, ownedVariable->data.pData);
  EXPECT_EQ("owned", std::string(reinterpret_cast<const char*>(ownedVariable->data.pData), ownedVariable->data.nData));
  EXPECT_EQ(TSDB_DATA_TYPE_DECIMAL, ownedDecimal->data.type);
  EXPECT_EQ(16U, ownedDecimal->data.nData);
  EXPECT_EQ(31, ownedDecimal->uid);
  EXPECT_EQ(32, ownedDecimal->vgId);
  ASSERT_NE(nullptr, sourceDecimal->data.pData);
  ASSERT_NE(nullptr, ownedDecimal->data.pData);
  EXPECT_NE(sourceDecimal->data.pData, ownedDecimal->data.pData);
  EXPECT_EQ(0, memcmp(kNestedDecimalBytes.data(), ownedDecimal->data.pData, kNestedDecimalBytes.size()));

  source.calcParam.resultNotifyContent[0] = 'X';
  sourceFixed->data.val = -1;
  sourceVariable->data.pData[0] = 'X';
  sourceDecimal->data.pData[0] = 0xff;
  destroyNestedPendingEventSource(&source);

  EXPECT_STREQ("{\"result\":2}", owned->calcParam.resultNotifyContent);
  EXPECT_EQ(1234, ownedFixed->data.val);
  EXPECT_EQ("owned", std::string(reinterpret_cast<const char*>(ownedVariable->data.pData), ownedVariable->data.nData));
  EXPECT_EQ(0, memcmp(kNestedDecimalBytes.data(), ownedDecimal->data.pData, kNestedDecimalBytes.size()));
  stDestroyNestedPendingCalcNode(&node);
  EXPECT_EQ(nullptr, node);
  stDestroyNestedPendingCalcNode(&node);
  EXPECT_EQ(nullptr, node);
}

