TEST_F(StreamNestedRealtimeTest, NestedTriggerIdUsesOnlyGidOrderedStartsAndOptionalEventIndex) {
  SLeafInstanceId identity = makeCanonicalTriggerIdentity();
  ASSERT_NE(nullptr, identity.lineage.pScopes);
  std::array<char, STREAM_NESTED_TRIGGER_ID_LEN> baseline = {};
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stBuildNestedTriggerId(identity.gid, &identity.lineage, identity.openingTs, -1, baseline.data()));

  auto* first = static_cast<SScopeInstanceId*>(taosArrayGet(identity.lineage.pScopes, 0));
  auto* second = static_cast<SScopeInstanceId*>(taosArrayGet(identity.lineage.pScopes, 1));
  ASSERT_NE(nullptr, first);
  ASSERT_NE(nullptr, second);
  first->triggerType += 1;
  first->nativeDiscriminator += 1;
  identity.triggerType -= 1;

  std::array<char, STREAM_NESTED_TRIGGER_ID_LEN> redundantFieldsChanged = {};
  ASSERT_EQ(TSDB_CODE_SUCCESS, stBuildNestedTriggerId(identity.gid, &identity.lineage, identity.openingTs, -1,
                                                      redundantFieldsChanged.data()));
  EXPECT_STREQ(baseline.data(), redundantFieldsChanged.data());

  const int32_t                                  firstEventIndex = INT32_C(0x01020304);
  const int32_t                                  secondEventIndex = INT32_C(0x04030201);
  std::array<char, STREAM_NESTED_TRIGGER_ID_LEN> eventChild = {};
  ASSERT_EQ(TSDB_CODE_SUCCESS, stBuildNestedTriggerId(identity.gid, &identity.lineage, identity.openingTs,
                                                      firstEventIndex, eventChild.data()));
  EXPECT_STREQ("5198a9ac954ec440440ed28cd3a4f5c5", eventChild.data());
  EXPECT_STRNE(baseline.data(), eventChild.data());

  std::array<char, STREAM_NESTED_TRIGGER_ID_LEN> secondEventChild = {};
  ASSERT_EQ(TSDB_CODE_SUCCESS, stBuildNestedTriggerId(identity.gid, &identity.lineage, identity.openingTs,
                                                      secondEventIndex, secondEventChild.data()));
  EXPECT_STRNE(eventChild.data(), secondEventChild.data());

  first->triggerType -= 1;
  first->nativeDiscriminator -= 1;
  identity.triggerType += 1;
  identity.gid += 1;
  expectNestedTriggerIdChanged(identity.gid, &identity.lineage, identity.openingTs, -1, baseline.data());
  identity.gid -= 1;
  first->openingTs += 1;
  expectNestedTriggerIdChanged(identity.gid, &identity.lineage, identity.openingTs, -1, baseline.data());
  first->openingTs -= 1;
  second->openingTs += 1;
  expectNestedTriggerIdChanged(identity.gid, &identity.lineage, identity.openingTs, -1, baseline.data());
  second->openingTs -= 1;
  identity.openingTs += 1;
  expectNestedTriggerIdChanged(identity.gid, &identity.lineage, identity.openingTs, -1, baseline.data());

  taosArrayDestroy(identity.lineage.pScopes);
}

