TEST_F(StreamNestedRealtimeTest, NestedEventNoticeBuilderOomPublishesNothingAndNextBatchUsesFrozenParent) {
  SStreamTriggerTask task = {};
  configureNestedNoticeTask(&task, 0);
  task.triggerType = STREAM_TRIGGER_EVENT;
  SStreamNestedPendingCalcEvent event = makeNestedPendingEvent();
  event.calcParam.notifyType = STRIGGER_EVENT_WINDOW_CLOSE;
  event.leafIdentity.triggerType = WINDOW_TYPE_EVENT;
  event.leafIdentity.nativeDiscriminator = 0;
  taosMemoryFreeClear(event.calcParam.extraNotifyContent);
  event.calcParam.extraNotifyContent =
      taosStrdup("{\"windowIndex\":0,\"parentTriggerId\":\"21d98cbc2c95e4238b634e5464885aef\"}");
  ASSERT_NE(nullptr, event.calcParam.extraNotifyContent);

  char*   pPayload = reinterpret_cast<char*>(static_cast<uintptr_t>(1));
  int32_t payloadLen = -1;
  Stub    reallocStub;
  reallocStub.set(taosMemRealloc, failNestedNoticeRealloc);
  EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY,
            streamBuildNestedTriggerWindowNotice(&task, "t1", event.leafIdentity.gid, STREAM_TRIGGER_EVENT, &event,
                                                 &pPayload, &payloadLen));
  reallocStub.reset(taosMemRealloc);
  EXPECT_EQ(nullptr, pPayload);
  EXPECT_EQ(0, payloadLen);
  EXPECT_STREQ("{\"windowIndex\":0,\"parentTriggerId\":\"21d98cbc2c95e4238b634e5464885aef\"}",
               event.calcParam.extraNotifyContent);

  SStreamTriggerNoticeBatch* pFailedBatch = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerNoticeBatchCreate(&pFailedBatch));
  reallocStub.set(taosMemRealloc, failNestedNoticeRealloc);
  EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY, stTriggerNoticeBatchStageWindow(pFailedBatch, &task, "t1", event.leafIdentity.gid,
                                                                     STREAM_TRIGGER_EVENT, &event));
  reallocStub.reset(taosMemRealloc);
  stTriggerNoticeBatchAbort(&pFailedBatch);
  EXPECT_EQ(nullptr, pFailedBatch);

  SStreamTriggerNoticeBatch* pNextBatch = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerNoticeBatchCreate(&pNextBatch));
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerNoticeBatchStageWindow(pNextBatch, &task, "t1", event.leafIdentity.gid,
                                                               STREAM_TRIGGER_EVENT, &event));
  resetNestedOutboxCapture();
  gNestedOutboxSendResults = {TSDB_CODE_SUCCESS};
  {
    Stub stub;
    stub.set(streamSendNotifyPayloadOnce, captureNestedOutboxSend);
    stTriggerNoticeBatchSend(&pNextBatch);
  }
  EXPECT_EQ(nullptr, pNextBatch);
  ASSERT_EQ(1U, gNestedOutboxPayloads.size());
  std::unique_ptr<cJSON, decltype(&cJSON_Delete)> root(cJSON_Parse(gNestedOutboxPayloads[0].c_str()), cJSON_Delete);
  ASSERT_NE(nullptr, root);
  cJSON* pNotice = nestedNoticeEvent(root.get());
  ASSERT_NE(nullptr, pNotice);
  EXPECT_STREQ("21d98cbc2c95e4238b634e5464885aef",
               cJSON_GetStringValue(cJSON_GetObjectItemCaseSensitive(pNotice, "parentTriggerId")));
  EXPECT_EQ(0, static_cast<int32_t>(cJSON_GetNumberValue(cJSON_GetObjectItemCaseSensitive(pNotice, "windowIndex"))));

  destroyNestedPendingEventSource(&event);
  destroyNestedNoticeTask(&task);
}

