struct PipelineCalcAttempt {
  PipelineCalcAttempt() = default;
  ~PipelineCalcAttempt() {
    cleanupTransport();
    tDestroySTriggerCalcRequest(&decoded);
  }
  PipelineCalcAttempt(const PipelineCalcAttempt&) = delete;
  PipelineCalcAttempt& operator=(const PipelineCalcAttempt&) = delete;
  PipelineCalcAttempt(PipelineCalcAttempt&& other) noexcept { moveFrom(other); }
  PipelineCalcAttempt& operator=(PipelineCalcAttempt&& other) noexcept {
    if (this != &other) {
      cleanupTransport();
      tDestroySTriggerCalcRequest(&decoded);
      moveFrom(other);
    }
    return *this;
  }

  SSTriggerAHandle* ahandle() const {
    return pSendInfo == nullptr ? nullptr : static_cast<SSTriggerAHandle*>(pSendInfo->param);
  }

  SSTriggerCalcRequest* pooledRequest() const {
    SSTriggerAHandle* pAhandle = ahandle();
    return pAhandle == nullptr ? nullptr : static_cast<SSTriggerCalcRequest*>(pAhandle->param);
  }

  void cleanupTransport() {
    if (pSendInfo != nullptr) {
      destroyAhandle(pSendInfo);
      pSendInfo = nullptr;
    }
    rpcFreeCont(requestCont);
    requestCont = nullptr;
    requestLen = 0;
  }

  SMsgSendInfo*               pSendInfo = nullptr;
  void*                       requestCont = nullptr;
  int32_t                     requestLen = 0;
  int32_t                     msgType = 0;
  SSTriggerCalcRequest        decoded = {};
  bool                        responseDispatched = false;
  bool                        transportFailed = false;
  uintptr_t                   pooledRequestAddress = 0;
  uintptr_t                   contextPolicyAddress = 0;
  uintptr_t                   ancestorContextAddress = 0;
  std::string                 serializedRequest;
  int32_t                     feedOrdinal = -1;
  bool                        tailDrain = false;
  std::vector<ParityEmission> emissions;

 private:
  void moveFrom(PipelineCalcAttempt& other) {
    pSendInfo = other.pSendInfo;
    requestCont = other.requestCont;
    requestLen = other.requestLen;
    msgType = other.msgType;
    decoded = other.decoded;
    responseDispatched = other.responseDispatched;
    transportFailed = other.transportFailed;
    pooledRequestAddress = other.pooledRequestAddress;
    contextPolicyAddress = other.contextPolicyAddress;
    ancestorContextAddress = other.ancestorContextAddress;
    serializedRequest = std::move(other.serializedRequest);
    feedOrdinal = other.feedOrdinal;
    tailDrain = other.tailDrain;
    emissions = std::move(other.emissions);
    other.pSendInfo = nullptr;
    other.requestCont = nullptr;
    other.requestLen = 0;
    other.msgType = 0;
    other.decoded = {};
  }
};

