    if (dataIndex < 0) dataIndex = findPull(STRIGGER_PULL_WAL_DATA_NEW, readerTaskId);
    if (dataIndex < 0) dataIndex = findPull(STRIGGER_PULL_WAL_META_NEW, readerTaskId);
