TEST_F(StreamNestedRecoveryTest, DeferredCheckpointKeepsBytesVersionProgressAndClock) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 7}}, {}, 0, &checkpoint));
  const std::vector<uint8_t> storedCheckpointBefore = checkpoint;
  ASSERT_FALSE(storedCheckpointBefore.empty());
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  ASSERT_EQ(1, harness.pendingRecoverySendCount());
  ASSERT_TRUE(harness.holdRecoverySend(0));
  RecoveryLiveState liveState;
  ASSERT_TRUE(seedRecoveryLiveState(&harness, false, &liveState, true));
  const SSTriggerWalProgress* pProgress = recoveryWalProgress(harness, RealtimePipelineHarness::kVgId);
  ASSERT_NE(nullptr, pProgress);
  const WalProgressSnapshot progressBefore = snapshotWalProgress(pProgress);

  constexpr int64_t checkpointInterval = 10 * NANOSECOND_PER_MINUTE;
  const int64_t     turnNow = 20 * checkpointInterval;
  const int64_t     checkpointClock = turnNow - checkpointInterval - 1;
  harness.context()->lastCheckpointTime = checkpointClock;
  atomic_store_32(&harness.task()->checkpointVersion, 71);
  Stub clockStub;
  clockStub.set(taosClockGetTime, captureRealtimePipelineTurnClock);
  resetRealtimePipelineTurnClock(turnNow, 0, turnNow);
  ScopedCheckpointGenerationProbe checkpointProbe(TSDB_CODE_SUCCESS, storedCheckpointBefore);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());

  EXPECT_TRUE(harness.task()->pendingPeriodicCheckpoint);
  EXPECT_EQ(0, checkpointProbe.probe().writes);
  EXPECT_EQ(0, checkpointProbe.probe().syncs);
  EXPECT_TRUE(checkpointProbe.probe().bytes.empty());
  EXPECT_EQ(storedCheckpointBefore, checkpointProbe.probe().storedBytes);
  EXPECT_EQ(71, atomic_load_32(&harness.task()->checkpointVersion));
  expectWalProgressUnchanged(pProgress, progressBefore);
  expectRecoveryLiveStateUnchanged(&harness, liveState);
  EXPECT_EQ(checkpointClock, harness.context()->lastCheckpointTime);
}

