TEST_F(StreamNestedRecoveryTest, ReplayLedgerMismatchAbortsBeforeShadowMutation) {
  enum class Mismatch { RequestCursor, Endpoint, EarlyEof, ExtraPage };
  for (Mismatch mismatch : {Mismatch::RequestCursor, Mismatch::Endpoint, Mismatch::EarlyEof, Mismatch::ExtraPage}) {
    SCOPED_TRACE(static_cast<int32_t>(mismatch));
    RealtimePipelineHarness harness;
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
    std::vector<uint8_t> checkpoint;
    ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 9}}, {}, 0, &checkpoint));
    harness.setCheckpointBytes(std::move(checkpoint));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 7, 700));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 9, 900));
    ASSERT_EQ(1, harness.pendingRecoverySendCount());
    ASSERT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY, harness.pendingRecoverySend(0)->recoveryToken.phase);
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
    SSTriggerNestedRecovery*   pRecovery = harness.task()->pNestedRecovery;
    ScopedNestedRecoveryRetain recoveryRetain(pRecovery);
    SSTriggerNestedWalReader* pReader = static_cast<SSTriggerNestedWalReader*>(taosArrayGet(pRecovery->pWalReaders, 0));
    ASSERT_NE(nullptr, pReader);
    ASSERT_EQ(2, taosArrayGetSize(pReader->pValidateLedger));
    ASSERT_NE(nullptr, pRecovery->pShadowBundle);
    SSTriggerRealtimeContext* pShadow = pRecovery->pShadowBundle->pContext;
    ASSERT_NE(nullptr, pShadow);
    EXPECT_EQ(0, tSimpleHashGetSize(pShadow->pGroups));
    const auto* pShadowProgress = static_cast<const SSTriggerWalProgress*>(tSimpleHashGet(
        pShadow->pReaderWalProgress, &RealtimePipelineHarness::kVgId, sizeof(RealtimePipelineHarness::kVgId)));
    ASSERT_NE(nullptr, pShadowProgress);
    const WalProgressSnapshot shadowProgressBefore = snapshotWalProgress(pShadowProgress);

    int64_t endpoint = 7;
    if (mismatch == Mismatch::RequestCursor) {
      auto* pPage = static_cast<SSTriggerNestedWalPage*>(taosArrayGet(pReader->pValidateLedger, 0));
      ASSERT_NE(nullptr, pPage);
      ++pPage->requestCursor;
    } else if (mismatch == Mismatch::Endpoint) {
      endpoint = 8;
    } else if (mismatch == Mismatch::EarlyEof) {
      endpoint = 9;
    } else {
      SSTriggerNestedWalAttempt* pAttempt = harness.pendingRecoveryAttempt(0);
      ASSERT_NE(nullptr, pAttempt);
      pAttempt->token.pageSeq = 2;
      pReader->expected.pageSeq = 2;
    }

    EXPECT_NE(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, endpoint, endpoint * 100));
    EXPECT_EQ(nullptr, harness.task()->pNestedRecovery);
    ASSERT_EQ(pRecovery, harness.task()->pRetiredNestedRecoveries);
    EXPECT_NE(TSDB_CODE_SUCCESS, harness.task()->nestedRecoveryError);
    EXPECT_EQ(0, harness.pendingRecoverySendCount());
    ASSERT_NE(nullptr, pRecovery->pShadowBundle);
    ASSERT_EQ(pShadow, pRecovery->pShadowBundle->pContext);
    EXPECT_EQ(0, tSimpleHashGetSize(pShadow->pGroups));
    pShadowProgress = static_cast<const SSTriggerWalProgress*>(tSimpleHashGet(
        pShadow->pReaderWalProgress, &RealtimePipelineHarness::kVgId, sizeof(RealtimePipelineHarness::kVgId)));
    expectWalProgressUnchanged(pShadowProgress, shadowProgressBefore);
    EXPECT_EQ(0, tSimpleHashGetSize(harness.context()->pGroups));
    recoveryRetain.reset();
  }
}

TEST_F(StreamNestedRecoveryTest, ReplayRejectsDeleteDropGapNoProgressAndOvershoot) {
  enum class InvalidPage { Delete, Drop, RetentionGap, NoProgress, Overshoot };
  for (InvalidPage invalid : {InvalidPage::Delete, InvalidPage::Drop, InvalidPage::RetentionGap,
                              InvalidPage::NoProgress, InvalidPage::Overshoot}) {
    SCOPED_TRACE(static_cast<int32_t>(invalid));
    RealtimePipelineHarness harness;
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
    std::vector<uint8_t> checkpoint;
    ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 7}}, {}, 0, &checkpoint));
    harness.setCheckpointBytes(std::move(checkpoint));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 7, 700));
    ASSERT_EQ(1, harness.pendingRecoverySendCount());

    int32_t code = TSDB_CODE_SUCCESS;
    switch (invalid) {
      case InvalidPage::Delete:
        code = harness.respondRecoverySuccess(0, 7, 700, true);
        break;
      case InvalidPage::Drop:
        code = harness.respondRecoverySuccess(0, 7, 700, false, true);
        break;
      case InvalidPage::RetentionGap:
        code = harness.respondRecoveryNoData(0, 7, 0);
        break;
      case InvalidPage::NoProgress:
        code = harness.respondRecoverySuccess(0, 5, 500);
        break;
      case InvalidPage::Overshoot:
        code = harness.respondRecoverySuccess(0, 8, 800);
        break;
    }
    EXPECT_NE(TSDB_CODE_SUCCESS, code);
    EXPECT_EQ(nullptr, harness.task()->pNestedRecovery);
    EXPECT_EQ(0, tSimpleHashGetSize(harness.context()->pGroups));
    EXPECT_EQ(0, harness.calcAttemptCount());
    EXPECT_EQ(0, harness.noticeSendCount());
  }
}

TEST_F(StreamNestedRecoveryTest, ReplayMultiPageMultiReaderAdvancesEachReaderExactlyOnce) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, true, 0, false, 2));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint(
      {{RealtimePipelineHarness::kVgId, 5, 9}, {RealtimePipelineHarness::kVgId + 1, 6, 10}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 7, 700));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 8, 800));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 9, 900));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 10, 1000));
  ASSERT_EQ(1, harness.pendingRecoverySendCount());
  EXPECT_EQ(RealtimePipelineHarness::kReaderTaskId, harness.pendingRecoverySend(0)->readerTaskId);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryNoData(0, 7, 700));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryNoData(0, 9, 900));
  ASSERT_EQ(1, harness.pendingRecoverySendCount());
  EXPECT_EQ(RealtimePipelineHarness::kReaderTaskId + 1, harness.pendingRecoverySend(0)->readerTaskId);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryNoData(0, 8, 800));
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryNoData(0, 10, 1000));

  EXPECT_EQ(0, harness.pendingRecoverySendCount());
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  EXPECT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY_DRAINED, harness.task()->pNestedRecovery->phase);
  ASSERT_EQ(2, taosArrayGetSize(harness.task()->pNestedRecovery->pWalReaders));
  for (int32_t i = 0; i < 2; ++i) {
    const auto* pReader =
        static_cast<const SSTriggerNestedWalReader*>(taosArrayGet(harness.task()->pNestedRecovery->pWalReaders, i));
    ASSERT_NE(nullptr, pReader);
    EXPECT_TRUE(pReader->completed);
    EXPECT_EQ(2U, pReader->nextPageSeq);
    EXPECT_EQ(pReader->savedVer, pReader->cursor);
    EXPECT_FALSE(pReader->expectedValid);
  }
  EXPECT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
}

TEST_F(StreamNestedRecoveryTest, RecoverySuppressesPublicationAndPreservesShadowEffects) {
  struct PublicationCase {
    const char* name;
    int64_t     calcEvents;
    int32_t     notifyEvents;
    bool        hasNotifyDestination;
    bool        expectShadowPendingCalc;
  };
  constexpr std::array<PublicationCase, 3> cases = {{
      {.name = "calc-and-notify",
       .calcEvents = STRIGGER_EVENT_WINDOW_CLOSE,
       .notifyEvents = STRIGGER_EVENT_WINDOW_CLOSE,
       .hasNotifyDestination = true,
       .expectShadowPendingCalc = true},
      {.name = "notify-only",
       .calcEvents = STRIGGER_EVENT_WINDOW_NONE,
       .notifyEvents = STRIGGER_EVENT_WINDOW_CLOSE,
       .hasNotifyDestination = true,
       .expectShadowPendingCalc = false},
      {.name = "notify-without-destination",
       .calcEvents = STRIGGER_EVENT_WINDOW_NONE,
       .notifyEvents = STRIGGER_EVENT_WINDOW_CLOSE,
       .hasNotifyDestination = false,
       .expectShadowPendingCalc = false},
  }};

  for (const PublicationCase& testCase : cases) {
    SCOPED_TRACE(testCase.name);
    RealtimePipelineHarness harness;
    harness.enableNestedTrowsCacheProjection();
    const bool              initialized =
        testCase.hasNotifyDestination
                         ? harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, testCase.calcEvents,
                                        testCase.notifyEvents, 0, 1, true, 0, false, 1, false, {"ws://recovery-publication.test"})
                         : harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, testCase.calcEvents,
                                        testCase.notifyEvents, 0, 1, true, 0, false, 1, false, {});
    ASSERT_TRUE(initialized);
    std::vector<uint8_t> checkpoint;
    ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 1, 2}}, {}, 0, &checkpoint));
    harness.setCheckpointBytes(std::move(checkpoint));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 2, 200));
    ASSERT_EQ(1, harness.pendingRecoverySendCount());
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery->pShadowBundle);
    SSTriggerRealtimeContext* pShadow = harness.task()->pNestedRecovery->pShadowBundle->pContext;
    ASSERT_NE(nullptr, pShadow);

    const auto* pLiveProgress = static_cast<const SSTriggerWalProgress*>(
        tSimpleHashGet(harness.context()->pReaderWalProgress, &RealtimePipelineHarness::kVgId,
                       sizeof(RealtimePipelineHarness::kVgId)));
    ASSERT_NE(nullptr, pLiveProgress);
    const WalProgressSnapshot liveProgressBefore = snapshotWalProgress(pLiveProgress);
    const int32_t             liveGroupCount = tSimpleHashGetSize(harness.context()->pGroups);
    const int64_t             liveLatestVersionTime = atomic_load_64(&harness.task()->latestVersionTime);
    const int32_t             queuedControlCount = harness.queuedControlCount();
    const int32_t             queuedWakeCount = harness.queuedRealtimeStartCount();

    const SScopeInstanceId outerScope = {
        .layerIndex = 0, .triggerType = WINDOW_TYPE_SESSION, .openingTs = 1000, .nativeDiscriminator = 0};
    SLeafInstanceId identity = {
        .gid = RealtimePipelineHarness::kGid,
        .lineage = {.pScopes = taosArrayInit(1, sizeof(SScopeInstanceId))},
        .triggerType = WINDOW_TYPE_SESSION,
        .openingTs = 1000,
        .nativeDiscriminator = 0,
    };
    ASSERT_NE(nullptr, identity.lineage.pScopes);
    ASSERT_NE(nullptr, taosArrayPush(identity.lineage.pScopes, &outerScope));
    const SStreamCacheScope cacheScope = {
        .gid = identity.gid,
        .lineage = {.pScopes = identity.lineage.pScopes},
    };

    int32_t shadowCacheRows = -1;
    int32_t liveCacheRows = -1;
    ASSERT_EQ(TSDB_CODE_SUCCESS, countRecoveryCacheScopeRows(pShadow->pCalcDataCache, &cacheScope, &shadowCacheRows));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              countRecoveryCacheScopeRows(harness.context()->pCalcDataCache, &cacheScope, &liveCacheRows));
    ASSERT_EQ(0, shadowCacheRows);
    ASSERT_EQ(0, liveCacheRows);

    Stub waitListStub;
    gRealtimePipelineWaitStreamId = harness.task()->task.streamId;
    gRealtimePipelineWaitTaskId = harness.task()->task.taskId;
    gRealtimePipelineWaitSessionId = harness.context()->sessionId;
    gRealtimePipelineWaitCaptureCount = 0;
    gRealtimePipelineWaitCaptured = false;
    gRealtimePipelineWaitInfo = {};
    gRealtimePipelineWaitAppendCode = TSDB_CODE_SUCCESS;
    waitListStub.set(tdListAppend, captureRealtimePipelineWaitAppend);
    ScopedRecoveryPublicationProbe publicationProbe;

    ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryData(0, {1000, 1015}, {1, 2}, 1015));

    ASSERT_EQ(TSDB_CODE_SUCCESS, countRecoveryCacheScopeRows(pShadow->pCalcDataCache, &cacheScope, &shadowCacheRows));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              countRecoveryCacheScopeRows(harness.context()->pCalcDataCache, &cacheScope, &liveCacheRows));
    EXPECT_EQ(0, shadowCacheRows);
    EXPECT_EQ(0, liveCacheRows);

    auto* ppShadowGroup = static_cast<SSTriggerRealtimeGroup**>(
        tSimpleHashGet(pShadow->pGroups, &RealtimePipelineHarness::kGid, sizeof(RealtimePipelineHarness::kGid)));
    ASSERT_NE(nullptr, ppShadowGroup);
    ASSERT_NE(nullptr, *ppShadowGroup);
    SSTriggerRealtimeGroup* pShadowGroup = *ppShadowGroup;
    const int64_t           shadowPendingCalc =
        pShadowGroup->pPendingCalcParams.neles + pShadowGroup->pPendingParWinCalcParams.neles +
        listNEles(&pShadowGroup->pendingNestedEvents) + listNEles(&pShadowGroup->pendingNestedParWinEvents);
    if (testCase.expectShadowPendingCalc) {
      EXPECT_GT(shadowPendingCalc, 0);
    } else {
      EXPECT_EQ(0, shadowPendingCalc);
    }

    expectWalProgressUnchanged(pLiveProgress, liveProgressBefore);
    EXPECT_EQ(liveGroupCount, tSimpleHashGetSize(harness.context()->pGroups));
    EXPECT_EQ(0, TD_DLIST_NELES(&harness.context()->groupsToCheck));
    EXPECT_EQ(liveLatestVersionTime, atomic_load_64(&harness.task()->latestVersionTime));
    EXPECT_EQ(nullptr, harness.context()->pCalcReq);
    EXPECT_EQ(0, listNEles(&harness.context()->retryCalcReqs));
    EXPECT_EQ(0, listNEles(&harness.context()->dropTableReqs));
    EXPECT_EQ(0, harness.calcSendCount());
    EXPECT_EQ(0, harness.calcAttemptCount());
    EXPECT_TRUE(harness.droppedGids().empty());
    EXPECT_EQ(0, harness.noticeSendCount());
    EXPECT_EQ(0, publicationProbe.noticeBatchSendCount());
    EXPECT_EQ(0, listNEles(harness.task()->pRecalcRequests));
    EXPECT_EQ(queuedControlCount, harness.queuedControlCount());
    EXPECT_EQ(queuedWakeCount, harness.queuedRealtimeStartCount());
    EXPECT_FALSE(gRealtimePipelineWaitCaptured);
    EXPECT_EQ(0, gRealtimePipelineWaitCaptureCount);
    EXPECT_EQ(0, harness.pendingRecoverySendCount());
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
    EXPECT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY_DRAINED, harness.task()->pNestedRecovery->phase);
    EXPECT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
    ASSERT_EQ(nullptr, harness.task()->pNestedRecovery);
    EXPECT_EQ(0, pShadowGroup->pPendingCalcParams.neles + pShadowGroup->pPendingParWinCalcParams.neles +
                     listNEles(&pShadowGroup->pendingNestedEvents) +
                     listNEles(&pShadowGroup->pendingNestedParWinEvents));
    taosArrayDestroy(identity.lineage.pScopes);
  }
}

TEST_F(StreamNestedRecoveryTest, ReplayShadowDrainsAllGroupsPastCalcPressure) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 1, 2}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 2, 200));
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery->pShadowBundle);
  SSTriggerRealtimeContext* pShadow = harness.task()->pNestedRecovery->pShadowBundle->pContext;
  ASSERT_NE(nullptr, pShadow);

  constexpr int32_t pressureRows = STREAM_CALC_REQ_MAX_WIN_NUM + 2;
  PipelineWalGroup  pressure = {.gid = RealtimePipelineHarness::kGid,
                                .uid = RealtimePipelineHarness::kUid,
                                .timestamps = std::vector<TSKEY>(pressureRows),
                                .values = std::vector<int32_t>(pressureRows, 1),
                                .version = 2};
  for (int32_t i = 0; i < pressureRows; ++i) pressure.timestamps[i] = 1000 + static_cast<TSKEY>(i) * 30;
  PipelineWalGroup              second = {.gid = RealtimePipelineHarness::kGid + 1,
                                          .uid = RealtimePipelineHarness::kUid + 1,
                                          .timestamps = {1000},
                                          .values = {1},
                                          .version = 2};
  std::vector<PipelineWalGroup> groups;
  groups.push_back(std::move(pressure));
  groups.push_back(std::move(second));

  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryGroups(0, groups));
  EXPECT_EQ(2, tSimpleHashGetSize(pShadow->pGroups));
  EXPECT_EQ(0, TD_DLIST_NELES(&pShadow->groupsToCheck));
  EXPECT_EQ(0, harness.calcAttemptCount());
  EXPECT_EQ(0, harness.noticeSendCount());
  EXPECT_EQ(0, listNEles(harness.task()->pRecalcRequests));
  EXPECT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
}

