TEST_F(StreamNestedRecoveryTest, ValidatesEveryVnodeBeforeFirstScratchMutation) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, true, 0, false, 2));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint(
      {{RealtimePipelineHarness::kVgId, 5, 7}, {RealtimePipelineHarness::kVgId + 1, 6, 8}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  ASSERT_EQ(2, harness.pendingRecoverySendCount());
  const PipelinePendingSend* pInitialFirst = harness.pendingRecoverySend(0);
  const PipelinePendingSend* pInitialSecond = harness.pendingRecoverySend(1);
  ASSERT_NE(nullptr, pInitialFirst);
  ASSERT_NE(nullptr, pInitialSecond);
  EXPECT_NE(pInitialFirst->recoveryToken.vgId, pInitialSecond->recoveryToken.vgId);
  EXPECT_NE(pInitialFirst->recoveryToken.taskId, pInitialSecond->recoveryToken.taskId);
  EXPECT_FALSE(isEpsetEqual(&pInitialFirst->recoveryToken.endpoint, &pInitialSecond->recoveryToken.endpoint));
  ASSERT_EQ(2, taosArrayGetSize(harness.task()->pNestedRecovery->pWalReaders));
  for (int32_t i = 0; i < 2; ++i) {
    const auto* pReader =
        static_cast<const SSTriggerNestedWalReader*>(taosArrayGet(harness.task()->pNestedRecovery->pWalReaders, i));
    ASSERT_NE(nullptr, pReader);
    ASSERT_NE(nullptr, pReader->pValidateLedger);
    EXPECT_EQ(0, taosArrayGetSize(pReader->pValidateLedger));
  }
  const int32_t       originalGroupCount = tSimpleHashGetSize(harness.context()->pGroups);
  RecoveryShadowProbe probe;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRecoverySuccess(0, 7, 700, false, false, installRecoveryShadowProbe, &probe));
  EXPECT_EQ(STRIGGER_NESTED_RECOVERY_VALIDATE, harness.task()->pNestedRecovery->phase);
  EXPECT_EQ(originalGroupCount, tSimpleHashGetSize(harness.context()->pGroups));
  EXPECT_EQ(0, TD_DLIST_NELES(&harness.context()->groupsToCheck));
  EXPECT_EQ(0, probe.bundleAllocCalls);
  EXPECT_EQ(0, probe.contextAllocCalls);
  EXPECT_EQ(0, probe.detachedCreateCalls);
  const SSTriggerWalProgress* pFirst = recoveryWalProgress(harness, RealtimePipelineHarness::kVgId);
  const SSTriggerWalProgress* pSecond = recoveryWalProgress(harness, RealtimePipelineHarness::kVgId + 1);
  ASSERT_NE(nullptr, pFirst);
  ASSERT_NE(nullptr, pSecond);
  EXPECT_EQ(5, pFirst->doneVer);
  EXPECT_EQ(5, pFirst->lastScanVer);
  EXPECT_EQ(6, pSecond->doneVer);
  EXPECT_EQ(6, pSecond->lastScanVer);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 8, 800));
  EXPECT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY, harness.task()->pNestedRecovery->phase);
  EXPECT_EQ(1, probe.bundleAllocCalls);
  EXPECT_EQ(1, probe.contextAllocCalls);
  EXPECT_EQ(1, probe.detachedCreateCalls);
  EXPECT_EQ(0, probe.registeredCacheInitCalls);
  EXPECT_EQ(0, probe.sequenceErrors);
  EXPECT_EQ(RecoveryShadowProbeStage::Complete, probe.stage);
  EXPECT_NE(probe.pShadowBundle, static_cast<void*>(probe.pShadowContext));
  EXPECT_EQ(originalGroupCount, tSimpleHashGetSize(harness.context()->pGroups));
  EXPECT_EQ(0, TD_DLIST_NELES(&harness.context()->groupsToCheck));
}

TEST_F(StreamNestedRecoveryTest, ShadowInitUsesDetachedRealtimeSessionCacheAndLeavesLiveRegistration) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.prepareStartCode());
  ASSERT_NE(nullptr, harness.context());
  void* const liveCache = harness.context()->pCalcDataCache;
  ASSERT_NE(nullptr, liveCache);
  harness.task()->nestedRecoveryGeneration = 0x1234;

  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 7}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  const uint64_t recoveryGeneration = harness.task()->pNestedRecovery->generation;
  ASSERT_NE(static_cast<uint64_t>(kRecoveryRealtimeSessionId), recoveryGeneration);

  RecoveryShadowProbe probe;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRecoverySuccess(0, 7, 700, false, false, installRecoveryShadowProbe, &probe));
  EXPECT_EQ(1, probe.detachedCreateCalls);
  EXPECT_EQ(RealtimePipelineHarness::kStreamId, probe.detachedStreamId);
  EXPECT_EQ(RealtimePipelineHarness::kTaskId, probe.detachedTaskId);
  EXPECT_EQ(kRecoveryRealtimeSessionId, probe.detachedSessionId);
  EXPECT_NE(static_cast<int64_t>(recoveryGeneration), probe.detachedSessionId);
  EXPECT_NE(nullptr, probe.pDetachedCache);
  EXPECT_NE(liveCache, probe.pDetachedCache);
  EXPECT_EQ(0, probe.replaceCalls);
  EXPECT_EQ(0, probe.registeredCacheInitCalls);
  EXPECT_EQ(0, probe.sequenceErrors);
  EXPECT_EQ(RecoveryShadowProbeStage::Complete, probe.stage);
  EXPECT_NE(probe.pShadowBundle, static_cast<void*>(probe.pShadowContext));

  SStreamDataCacheLease* pLease = nullptr;
  void*                  pRegisteredCache = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            acquireStreamDataCacheLease(RealtimePipelineHarness::kStreamId, RealtimePipelineHarness::kTaskId,
                                        kRecoveryRealtimeSessionId, &pLease, &pRegisteredCache));
  EXPECT_EQ(liveCache, pRegisteredCache);
  releaseStreamDataCacheLease(&pLease);
  pRegisteredCache = nullptr;
  EXPECT_EQ(TSDB_CODE_INVALID_PARA,
            acquireStreamDataCacheLease(RealtimePipelineHarness::kStreamId, RealtimePipelineHarness::kTaskId,
                                        static_cast<int64_t>(recoveryGeneration), &pLease, &pRegisteredCache));
  EXPECT_EQ(nullptr, pLease);
  EXPECT_EQ(nullptr, pRegisteredCache);
}

