TEST_F(StreamNestedRecoveryTest, NetworkRetryDeepOwnsTokenAndRequestPayload) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 7}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  ASSERT_EQ(1, harness.pendingRecoverySendCount());
  const PipelinePendingSend first = *harness.pendingRecoverySend(0);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryError(0, TSDB_CODE_RPC_NETWORK_UNAVAIL));
  ASSERT_EQ(1, harness.pendingRecoverySendCount());
  const PipelinePendingSend second = *harness.pendingRecoverySend(0);
  EXPECT_EQ(first.recoveryToken.generation, second.recoveryToken.generation);
  EXPECT_EQ(first.recoveryToken.phase, second.recoveryToken.phase);
  EXPECT_EQ(first.recoveryToken.vgId, second.recoveryToken.vgId);
  EXPECT_EQ(first.recoveryToken.taskId, second.recoveryToken.taskId);
  EXPECT_EQ(first.recoveryToken.pageSeq, second.recoveryToken.pageSeq);
  EXPECT_EQ(first.recoveryToken.requestCursor, second.recoveryToken.requestCursor);
  EXPECT_TRUE(isEpsetEqual(&first.recoveryToken.endpoint, &second.recoveryToken.endpoint));
  EXPECT_EQ(first.recoveryPayload, second.recoveryPayload);
  EXPECT_NE(first.recoveryAttemptAddress, second.recoveryAttemptAddress);
  EXPECT_NE(first.recoveryPayloadAddress, second.recoveryPayloadAddress);
  EXPECT_NE(first.recoveryAttemptSerial, second.recoveryAttemptSerial);
  EXPECT_NE(second.recoveryPayloadAddress, reinterpret_cast<uintptr_t>(second.pRequestCont));
  EXPECT_EQ(1, atomic_load_32(&harness.task()->pNestedRecovery->inFlight));
  EXPECT_EQ(0, listNEles(&harness.context()->retryPullReqs));
  EXPECT_EQ(0, harness.queuedRealtimeStartCount());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryError(0, TSDB_CODE_RPC_NETWORK_UNAVAIL));
  ASSERT_EQ(1, harness.pendingRecoverySendCount());
  const PipelinePendingSend* pThird = harness.pendingRecoverySend(0);
  ASSERT_NE(nullptr, pThird);
  EXPECT_EQ(second.recoveryPayload, pThird->recoveryPayload);
  EXPECT_NE(second.recoveryAttemptSerial, pThird->recoveryAttemptSerial);
  EXPECT_EQ(1, atomic_load_32(&harness.task()->pNestedRecovery->inFlight));
  EXPECT_EQ(0, listNEles(&harness.context()->retryPullReqs));
  EXPECT_EQ(0, harness.queuedRealtimeStartCount());
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 7, 700));
}

