TEST_F(StreamNestedRecoveryTest, OldGenerationResponseDuringNextRecoveryIsSafeDrop) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, true, 0, false, 2));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint(
      {{RealtimePipelineHarness::kVgId, 5, 7}, {RealtimePipelineHarness::kVgId + 1, 6, 8}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  SSTriggerNestedRecovery* pOldRecovery = harness.task()->pNestedRecovery;
  ASSERT_NE(nullptr, pOldRecovery);
  const uint64_t oldGeneration = pOldRecovery->generation;
  ASSERT_TRUE(harness.holdRecoverySend(1));
  SSTriggerNestedWalAttempt* pAttempt = harness.pendingRecoveryAttempt(0);
  ASSERT_NE(nullptr, pAttempt);
  ++pAttempt->token.pageSeq;
  ASSERT_NE(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 7, 700));
  ASSERT_EQ(nullptr, harness.task()->pNestedRecovery);
  ASSERT_EQ(pOldRecovery, harness.task()->pRetiredNestedRecoveries);

  std::vector<uint8_t> nextCheckpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint(
      {{RealtimePipelineHarness::kVgId, 7, 9}, {RealtimePipelineHarness::kVgId + 1, 8, 10}}, {}, 0, &nextCheckpoint));
  harness.setCheckpointBytes(std::move(nextCheckpoint));
  harness.context()->haveReadCheckpoint = false;
  harness.task()->nestedRecoveryError = TSDB_CODE_SUCCESS;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  SSTriggerNestedRecovery* pNewRecovery = harness.task()->pNestedRecovery;
  ASSERT_NE(nullptr, pNewRecovery);
  ASSERT_NE(pOldRecovery, pNewRecovery);
  EXPECT_EQ(oldGeneration + 1, pNewRecovery->generation);
  ASSERT_EQ(2, harness.pendingRecoverySendCount());
  const int32_t queuedBefore = harness.queuedRealtimeStartCount();

  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.respondHeldRecoveryNoData(0, 8, 800));
  EXPECT_EQ(pNewRecovery, harness.task()->pNestedRecovery);
  EXPECT_EQ(STRIGGER_NESTED_RECOVERY_VALIDATE, pNewRecovery->phase);
  EXPECT_EQ(nullptr, harness.task()->pRetiredNestedRecoveries);
  EXPECT_EQ(2, harness.pendingRecoverySendCount());
  EXPECT_EQ(queuedBefore, harness.queuedRealtimeStartCount());
  EXPECT_EQ(0, listNEles(&harness.context()->retryPullReqs));
}

