TEST_F(StreamNestedRealtimeTest, RoutesNeedInputResponseToExactSource) {
  NestedRouteRuntimeFixture harness;
  ASSERT_TRUE(harness.deployNestedVirtualPair());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(2));
  ASSERT_EQ(2U, harness.nestedAttemptCount());

  CapturedPullAttempt* pSource0 = harness.findNestedAttempt(0);
  CapturedPullAttempt* pSource1 = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pSource0);
  ASSERT_NE(nullptr, pSource1);
  EXPECT_NE(pSource0->routeAddress, pSource1->routeAddress);
  EXPECT_EQ(STREAM_NESTED_INPUT_REALTIME, pSource0->route.owner);
  EXPECT_EQ(STREAM_NESTED_INPUT_REALTIME, pSource1->route.owner);
  EXPECT_EQ(STREAM_NESTED_CURSOR_NONE, pSource0->route.cursorFamily);
  EXPECT_EQ(STREAM_NESTED_CURSOR_NONE, pSource1->route.cursorFamily);
  EXPECT_EQ(0U, pSource0->route.rosterId);
  EXPECT_EQ(0U, pSource1->route.rosterId);
  EXPECT_EQ(0U, pSource0->route.cursorId);
  EXPECT_EQ(0U, pSource1->route.cursorId);
  EXPECT_EQ(0U, pSource0->route.snapshotLeaseId);
  EXPECT_EQ(0U, pSource1->route.snapshotLeaseId);
  EXPECT_EQ(0U, pSource0->route.pageSeq);
  EXPECT_EQ(0U, pSource1->route.pageSeq);
  EXPECT_EQ(-1, pSource0->route.rosterIndex);
  EXPECT_EQ(-1, pSource1->route.rosterIndex);
  EXPECT_EQ(0, pSource0->route.sourceIndex);
  EXPECT_EQ(1, pSource1->route.sourceIndex);
  EXPECT_EQ(0, pSource0->route.subSourceIndex);
  EXPECT_EQ(0, pSource1->route.subSourceIndex);
  EXPECT_EQ(kNestedRealtimeSessionId, pSource0->route.sessionId);
  EXPECT_EQ(pSource0->route.sessionId, pSource1->route.sessionId);
  EXPECT_EQ(NestedRouteRuntimeFixture::kGid, pSource0->route.ownerId);
  EXPECT_EQ(pSource0->route.ownerId, pSource1->route.ownerId);
  EXPECT_EQ(pSource0->route.generation, pSource1->route.generation);
  EXPECT_EQ(pSource0->route.pullType, pSource0->request.value().base.type);
  EXPECT_EQ(pSource1->route.pullType, pSource1->request.value().base.type);
  EXPECT_EQ(harness.reader(0).taskId, pSource0->route.readerTaskId);
  EXPECT_EQ(harness.reader(1).taskId, pSource1->route.readerTaskId);
  EXPECT_EQ(pSource0->route.readerTaskId, pSource0->request.value().base.readerTaskId);
  EXPECT_EQ(pSource1->route.readerTaskId, pSource1->request.value().base.readerTaskId);
  EXPECT_TRUE(isEpsetEqual(&pSource0->endpoint, &harness.reader(0).epset));
  EXPECT_TRUE(isEpsetEqual(&pSource1->endpoint, &harness.reader(1).epset));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pSource1, NestedRouteRuntimeFixture::kEventTs, 202));
  EXPECT_EQ(0, harness.calcSendCount());
  int32_t outerSessionRows = -1;
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.readOuterSessionRowCount(&outerSessionRows));
  EXPECT_EQ(0, outerSessionRows);
  bool noticePending = true;
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.confirmNoDeferredNotice(&noticePending));
  EXPECT_FALSE(noticePending);
  EXPECT_EQ(0, harness.noticeSendCount());
  ASSERT_NE(nullptr, harness.findNestedAttempt(0));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pSource0, NestedRouteRuntimeFixture::kEventTs, 101));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  ASSERT_EQ(1, harness.calcSendCount());
  ASSERT_NE(nullptr, harness.latestCalc());
  const SSTriggerCalcRequest* pCalc = harness.latestCalc();
  EXPECT_FALSE(pCalc->isMultiGroupCalc);
  EXPECT_EQ(NestedRouteRuntimeFixture::kGid, pCalc->gid);
  EXPECT_EQ(TSDB_CODE_SUCCESS, tValidateSTriggerCalcRequestAncestorContext(pCalc, true));
  ASSERT_NE(nullptr, pCalc->params);
  ASSERT_EQ(1, taosArrayGetSize(pCalc->params));
  const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalc->params, 0));
  ASSERT_NE(nullptr, pParam);
  EXPECT_EQ(2, pParam->wrownum);

  ASSERT_NE(nullptr, pCalc->pContextPolicy);
  ASSERT_NE(nullptr, pCalc->pContextPolicy->pEntries);
  ASSERT_EQ(1, taosArrayGetSize(pCalc->pContextPolicy->pEntries));
  const auto* pPolicy = static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pCalc->pContextPolicy->pEntries, 0));
  ASSERT_NE(nullptr, pPolicy);
  EXPECT_EQ(NestedRouteRuntimeFixture::kGid, pPolicy->gid);
  EXPECT_EQ(0, pPolicy->paramIndex);
  EXPECT_EQ(STREAM_CONTEXT_POLICY_ANCESTOR, pPolicy->contextPolicy);

  ASSERT_NE(nullptr, pCalc->pAncestorContext);
  ASSERT_NE(nullptr, pCalc->pAncestorContext->pParamContexts);
  ASSERT_EQ(1, taosArrayGetSize(pCalc->pAncestorContext->pParamContexts));
  EXPECT_EQ(0, taosArrayGetSize(pCalc->pAncestorContext->pReadScopeBindings));
  const auto* pContext =
      static_cast<const SStreamAncestorParamContext*>(taosArrayGet(pCalc->pAncestorContext->pParamContexts, 0));
  ASSERT_NE(nullptr, pContext);
  EXPECT_EQ(pPolicy->gid, pContext->leafIdentity.gid);
  EXPECT_EQ(pPolicy->paramIndex, pContext->paramIndex);
  ASSERT_NE(nullptr, pContext->leafIdentity.lineage.pScopes);
  ASSERT_GT(taosArrayGetSize(pContext->leafIdentity.lineage.pScopes), 0);

  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readCommittedRows(*pContext, &rows));
  const std::vector<ObservedScopedRow> expected = {
      {harness.tableUid(0), 101},
      {harness.tableUid(1), 202},
  };
  EXPECT_EQ(expected, rows);
}

