  int32_t respondVirtualMgmtReaders() {
    auto* pReq = static_cast<SStreamMgmtReq*>(atomic_load_ptr(&task_.task.pMgmtReq));
    if (pReq == nullptr || pReq->cont.pReqs == nullptr || taosArrayGetSize(pReq->cont.pReqs) != 2) {
      return TSDB_CODE_INTERNAL_ERROR;
    }
    SStreamMgmtRsp response = {};
    response.header.msgType = STREAM_MSG_ORIGTBL_READER_INFO;
    response.reqId = pReq->reqId;
    response.task = task_.task;
    response.cont.vgIds = taosArrayInit(2, sizeof(int32_t));
    response.cont.readerList = taosArrayInit(2, sizeof(SStreamTaskAddr));
    if (response.cont.vgIds == nullptr || response.cont.readerList == nullptr) {
      taosArrayDestroy(response.cont.vgIds);
      taosArrayDestroy(response.cont.readerList);
      return terrno;
    }
    for (int32_t i = 0; i < taosArrayGetSize(pReq->cont.pReqs); ++i) {
      const auto* pName = static_cast<const SStreamDbTableName*>(taosArrayGet(pReq->cont.pReqs, i));
      if (pName == nullptr) {
        taosArrayDestroy(response.cont.vgIds);
        taosArrayDestroy(response.cont.readerList);
        return TSDB_CODE_INTERNAL_ERROR;
      }
      int32_t nodeId = strcmp(pName->tbName, "physical_a") == 0 ? kOriginalNodeA : kOriginalNodeB;
      if (taosArrayPush(response.cont.vgIds, &nodeId) == nullptr) {
        taosArrayDestroy(response.cont.vgIds);
        taosArrayDestroy(response.cont.readerList);
        return terrno;
      }
    }
    SStreamTaskAddr readerA = {.taskId = kOriginalReaderTaskA, .nodeId = kOriginalNodeA};
    SStreamTaskAddr readerB = {.taskId = kOriginalReaderTaskB, .nodeId = kOriginalNodeB};
    if (addEpIntoEpSet(&readerA.epset, "virtual-original-a.test", 6841) != TSDB_CODE_SUCCESS ||
        addEpIntoEpSet(&readerB.epset, "virtual-original-b.test", 6842) != TSDB_CODE_SUCCESS ||
        taosArrayPush(response.cont.readerList, &readerA) == nullptr ||
        taosArrayPush(response.cont.readerList, &readerB) == nullptr) {
      taosArrayDestroy(response.cont.vgIds);
      taosArrayDestroy(response.cont.readerList);
      return TSDB_CODE_OUT_OF_MEMORY;
    }
    if (pReq != atomic_val_compare_exchange_ptr(&task_.task.pMgmtReq, pReq, nullptr)) {
      taosArrayDestroy(response.cont.vgIds);
      taosArrayDestroy(response.cont.readerList);
      return TSDB_CODE_INTERNAL_ERROR;
    }
    tFreeSStreamMgmtReq(pReq);
    taosMemoryFree(pReq);
    int32_t code = stTriggerTaskExecute(&task_, &response.header);
    taosArrayDestroy(response.cont.vgIds);
    taosArrayDestroy(response.cont.readerList);
    return code == TSDB_CODE_SUCCESS ? dispatchControl(kRealtimeSession) : code;
  }

