  int32_t respondAllVirtualLastTs() {
    int32_t code = TSDB_CODE_SUCCESS;
    while (CapturedPullAttempt* pAttempt = findPull(STRIGGER_PULL_LAST_TS, kRealtimeSession)) {
      const int64_t        readerTaskId = pAttempt->request.value().base.readerTaskId;
      std::vector<STsInfo> rows;
      if (readerTaskId == kOriginalReaderTaskA) rows.push_back({kPhysicalUidA, cutoff_});
      if (readerTaskId == kOriginalReaderTaskB) rows.push_back({kPhysicalUidB, cutoff_});
      code = respondTsRows(*pAttempt, rows);
      if (code != TSDB_CODE_SUCCESS) return code;
    }
    return code;
  }

  int32_t driveVirtualDiscovery(bool reverseLogicalOrder = false) {
    int32_t code = startVirtualDiscovery();
    if (code != TSDB_CODE_SUCCESS) return code;
    if (reverseLogicalOrder) {
      code = respondVirtualTableInfoForReader(kPartitionReaderTaskB);
      if (code == TSDB_CODE_SUCCESS) code = respondVirtualTableInfoForReader(kPartitionReaderTaskA);
    } else {
      code = respondAllVirtualTableInfo();
    }
    if (code != TSDB_CODE_SUCCESS) return code;
    code = respondVirtualMgmtReaders();
    if (code != TSDB_CODE_SUCCESS) return code;
    code = respondAllOriginalTableInfo();
    if (code != TSDB_CODE_SUCCESS) return code;
    code = respondAllSetTable();
    if (code != TSDB_CODE_SUCCESS) return code;
    return respondAllVirtualLastTs();
  }

  int32_t respondAllVirtualFirstTs() {
    int32_t code = TSDB_CODE_SUCCESS;
    while (CapturedPullAttempt* pAttempt = findPull(STRIGGER_PULL_FIRST_TS, kHistorySession)) {
      const int64_t        readerTaskId = pAttempt->request.value().base.readerTaskId;
      std::vector<STsInfo> rows;
      if (readerTaskId == kOriginalReaderTaskA) rows.push_back({kPhysicalUidA, kScanStart});
      if (readerTaskId == kOriginalReaderTaskB) rows.push_back({kPhysicalUidB, kScanStart + 1});
      code = respondTsRows(*pAttempt, rows);
      if (code != TSDB_CODE_SUCCESS) return code;
    }
    return code;
  }

  int32_t respondAllVirtualMetas(bool fullFirstPage = false) {
    int32_t code = TSDB_CODE_SUCCESS;
    while (CapturedPullAttempt* pAttempt = findPull(STRIGGER_PULL_TSDB_META, kHistorySession)) {
      const int64_t                     readerTaskId = pAttempt->request.value().base.readerTaskId;
      std::vector<NestedHistoryMetaRow> rows;
      if (readerTaskId == kOriginalReaderTaskA) {
        rows.push_back({kScanStart, kScanStart, kPhysicalUidA, 1});
      } else if (readerTaskId == kOriginalReaderTaskB) {
        rows.push_back({kScanStart + 1, kScanStart + 1, kPhysicalUidB, 1});
      }
      if (fullFirstPage && readerTaskId == kOriginalReaderTaskA) {
        rows.clear();
        rows.reserve(STREAM_RETURN_ROWS_NUM);
        rows.push_back({kScanStart, kScanStart, kPhysicalUidA, 1});
        for (int32_t row = 1; row < STREAM_RETURN_ROWS_NUM; ++row) {
          rows.push_back({kScanStart, kScanStart, 900000 + row, 1});
        }
      }
      code = rows.empty()
                 ? dispatchAttempt(*pAttempt, TDMT_STREAM_TRIGGER_PULL_RSP, TSDB_CODE_SUCCESS, OwnedRpcPayload(), 0)
                 : respondVirtualMetaBlock(*pAttempt, rows);
      if (code != TSDB_CODE_SUCCESS) return code;
    }
    return code;
  }

