  int32_t respondRowsAtTimestampSlot(int64_t uid, const std::vector<TSKEY>& decoyTimestamps,
                                     const std::vector<TSKEY>& eventTimestamps, const std::vector<int32_t>& values) {
    CapturedPullAttempt* pAttempt = findDataPull(uid);
    if (pAttempt == nullptr || decoyTimestamps.size() != eventTimestamps.size() ||
        eventTimestamps.size() != values.size()) {
      return TSDB_CODE_INTERNAL_ERROR;
    }
    SSDataBlock* pBlock = makeTimestampSlotBlock(decoyTimestamps, eventTimestamps, values);
    if (pBlock != nullptr) pBlock->info.id.uid = uid;
    return respondBlock(*pAttempt, pBlock);
  }

