struct NestedHistoryCandidateRecord {
  int32_t eventType;
  int64_t rowCount;
  TSKEY   openingTs;
  int64_t nativeDiscriminator;
  TSKEY   wstart;
  TSKEY   wend;
  TSKEY   prevTs;
  TSKEY   currentTs;
  int64_t wrownum;

  bool operator==(const NestedHistoryCandidateRecord& rhs) const {
    return eventType == rhs.eventType && rowCount == rhs.rowCount && openingTs == rhs.openingTs &&
           nativeDiscriminator == rhs.nativeDiscriminator && wstart == rhs.wstart && wend == rhs.wend &&
           prevTs == rhs.prevTs && currentTs == rhs.currentTs && wrownum == rhs.wrownum;
  }
};

struct NestedHistoryPeerSubmitRecord {
  TSKEY                                     timestamp;
  std::vector<int64_t>                      tableUids;
  std::vector<NestedHistoryCandidateRecord> candidates;

  bool operator==(const NestedHistoryPeerSubmitRecord& rhs) const {
    return timestamp == rhs.timestamp && tableUids == rhs.tableUids && candidates == rhs.candidates;
  }
};

struct NestedHistoryPeerRegistrationProbe {
  Stub                                       stub;
  std::vector<int64_t>                       addedTableUids;
  std::vector<int64_t>                       currentRoundTableUids;
  std::vector<std::vector<int64_t>>          roundTableUids;
  std::vector<NestedHistoryPeerSubmitRecord> submits;
  SStreamTriggerPeerMerger*                  pStartedMerger = nullptr;
  int32_t                                    firstNextSourceCount = -1;
  int32_t                                    nextCalls = 0;
  bool                                       roundStarted = false;
  bool                                       addAfterNext = false;
};

static NestedHistoryPeerRegistrationProbe* gNestedHistoryPeerRegistrationProbe = nullptr;

static int32_t captureNestedHistoryPeerAddSource(SStreamTriggerPeerMerger* pMerger, int64_t tableUid,
                                                 const SStreamTriggerPeerSourceOps* pOps, void* pSource) {
  NestedHistoryPeerRegistrationProbe* pProbe = gNestedHistoryPeerRegistrationProbe;
  pProbe->stub.reset(stTriggerMergerPeerAddSource);
  int32_t code = stTriggerMergerPeerAddSource(pMerger, tableUid, pOps, pSource);
  pProbe->stub.set(stTriggerMergerPeerAddSource, captureNestedHistoryPeerAddSource);
  if (code == TSDB_CODE_SUCCESS) {
    pProbe->addAfterNext = pProbe->addAfterNext || pProbe->roundStarted;
    if (pProbe->roundStarted) {
      pProbe->currentRoundTableUids.clear();
      pProbe->roundStarted = false;
    }
    pProbe->addedTableUids.push_back(tableUid);
    pProbe->currentRoundTableUids.push_back(tableUid);
  }
  return code;
}

static int32_t captureNestedHistoryPeerNext(SStreamTriggerPeerMerger* pMerger, EStreamTriggerPeerGroupStatus* pStatus,
                                            int32_t* pNeedSourceIndex, const SWindowChainPeerGroup** ppGroup) {
  NestedHistoryPeerRegistrationProbe* pProbe = gNestedHistoryPeerRegistrationProbe;
  if (!pProbe->roundStarted) {
    pProbe->roundTableUids.push_back(pProbe->currentRoundTableUids);
    pProbe->roundStarted = true;
    pProbe->pStartedMerger = pMerger;
  }
  if (pProbe->firstNextSourceCount < 0) {
    pProbe->firstNextSourceCount = static_cast<int32_t>(pProbe->addedTableUids.size());
  }
  ++pProbe->nextCalls;
  pProbe->stub.reset(stTriggerMergerNextPeerGroup);
  int32_t code = stTriggerMergerNextPeerGroup(pMerger, pStatus, pNeedSourceIndex, ppGroup);
  pProbe->stub.set(stTriggerMergerNextPeerGroup, captureNestedHistoryPeerNext);
  return code;
}

static int32_t captureNestedHistoryPeerPrepare(SWindowChainState* pState, const SWindowChainPeerGroup* pGroup,
                                               int64_t nowNs, SWindowChainSubmitResult* pResult,
                                               SWindowChainPeerGroupTxn** ppTxn) {
  NestedHistoryPeerSubmitRecord record = {.timestamp = pGroup == nullptr ? 0 : pGroup->ts};
  if (pGroup != nullptr && pGroup->pRows != nullptr) {
    for (int32_t i = 0; i < taosArrayGetSize(pGroup->pRows); ++i) {
      const auto* pRow = static_cast<const SWindowChainRowRef*>(taosArrayGet(pGroup->pRows, i));
      if (pRow != nullptr) record.tableUids.push_back(pRow->tableUid);
    }
    std::sort(record.tableUids.begin(), record.tableUids.end());
  }

  NestedHistoryPeerRegistrationProbe* pProbe = gNestedHistoryPeerRegistrationProbe;
  pProbe->stub.reset(stWindowChainPreparePeerGroup);
  int32_t code = stWindowChainPreparePeerGroup(pState, pGroup, nowNs, pResult, ppTxn);
  pProbe->stub.set(stWindowChainPreparePeerGroup, captureNestedHistoryPeerPrepare);
  if (code == TSDB_CODE_SUCCESS && pResult != nullptr && pResult->pCandidates != nullptr) {
    for (int32_t i = 0; i < taosArrayGetSize(pResult->pCandidates); ++i) {
      const auto* pCandidate = static_cast<const SLeafEventCandidate*>(taosArrayGet(pResult->pCandidates, i));
      if (pCandidate == nullptr) continue;
      record.candidates.push_back({.eventType = pCandidate->eventType,
                                   .rowCount = pCandidate->rowCount,
                                   .openingTs = pCandidate->instanceId.openingTs,
                                   .nativeDiscriminator = pCandidate->instanceId.nativeDiscriminator,
                                   .wstart = pCandidate->leafParam.wstart,
                                   .wend = pCandidate->leafParam.wend,
                                   .prevTs = pCandidate->leafParam.prevTs,
                                   .currentTs = pCandidate->leafParam.currentTs,
                                   .wrownum = pCandidate->leafParam.wrownum});
    }
  }
  pProbe->submits.push_back(std::move(record));
  return code;
}

static int32_t nestedHistoryLateSourcePeek(void*, SStreamTriggerPeerHead*, EStreamTriggerPeerSourceStatus* pStatus) {
  if (pStatus == nullptr) return TSDB_CODE_INVALID_PARA;
  *pStatus = STREAM_TRIGGER_PEER_SOURCE_EOF;
  return TSDB_CODE_SUCCESS;
}

static void nestedHistoryLateSourceConsume(void*) {}

class ScopedNestedHistoryPeerRegistrationProbe {
 public:
  ScopedNestedHistoryPeerRegistrationProbe() {
    gNestedHistoryPeerRegistrationProbe = &probe_;
    probe_.stub.set(stTriggerMergerPeerAddSource, captureNestedHistoryPeerAddSource);
    probe_.stub.set(stTriggerMergerNextPeerGroup, captureNestedHistoryPeerNext);
    probe_.stub.set(stWindowChainPreparePeerGroup, captureNestedHistoryPeerPrepare);
  }

  ~ScopedNestedHistoryPeerRegistrationProbe() {
    probe_.stub.reset(stWindowChainPreparePeerGroup);
    probe_.stub.reset(stTriggerMergerNextPeerGroup);
    probe_.stub.reset(stTriggerMergerPeerAddSource);
    gNestedHistoryPeerRegistrationProbe = nullptr;
  }

  ScopedNestedHistoryPeerRegistrationProbe(const ScopedNestedHistoryPeerRegistrationProbe&) = delete;
  ScopedNestedHistoryPeerRegistrationProbe& operator=(const ScopedNestedHistoryPeerRegistrationProbe&) = delete;

  const NestedHistoryPeerRegistrationProbe& get() const { return probe_; }

 private:
  NestedHistoryPeerRegistrationProbe probe_;
};

struct CanonicalNestedObservation {
  int64_t                             gid = 0;
  int8_t                              triggerType = 0;
  TSKEY                               openingTs = 0;
  int64_t                             nativeDiscriminator = 0;
  std::vector<SScopeInstanceId>       lineage;
  TSKEY                               wstart = 0;
  TSKEY                               wend = 0;
  int64_t                             wduration = 0;
  int64_t                             wrownum = 0;
  TSKEY                               prevTs = 0;
  TSKEY                               currentTs = 0;
  TSKEY                               nextTs = 0;
  TSKEY                               triggerTime = 0;
  int32_t                             notifyType = 0;
  int32_t                             contextPolicy = 0;
  std::vector<std::array<int64_t, 7>> snapshots;
  std::vector<ObservedScopedRow>      rows;

  bool operator==(const CanonicalNestedObservation& rhs) const {
    if (gid != rhs.gid || triggerType != rhs.triggerType || openingTs != rhs.openingTs ||
        nativeDiscriminator != rhs.nativeDiscriminator || wstart != rhs.wstart || wend != rhs.wend ||
        wduration != rhs.wduration || wrownum != rhs.wrownum || prevTs != rhs.prevTs || currentTs != rhs.currentTs ||
        nextTs != rhs.nextTs || notifyType != rhs.notifyType || contextPolicy != rhs.contextPolicy ||
        snapshots != rhs.snapshots || rows != rhs.rows || lineage.size() != rhs.lineage.size()) {
      return false;
    }
    for (size_t i = 0; i < lineage.size(); ++i) {
      if (lineage[i].layerIndex != rhs.lineage[i].layerIndex || lineage[i].triggerType != rhs.lineage[i].triggerType ||
          lineage[i].openingTs != rhs.lineage[i].openingTs ||
          lineage[i].nativeDiscriminator != rhs.lineage[i].nativeDiscriminator) {
        return false;
      }
    }
    return true;
  }
};

static bool captureCanonicalNestedObservation(const SStreamNestedPendingCalcEvent*  pEvent,
                                              const std::vector<ObservedScopedRow>& rows,
                                              CanonicalNestedObservation*           pObservation) {
  if (pEvent == nullptr || pObservation == nullptr || pEvent->leafIdentity.lineage.pScopes == nullptr ||
      pEvent->pSnapshots == nullptr) {
    return false;
  }
  CanonicalNestedObservation observation;
  observation.gid = pEvent->leafIdentity.gid;
  observation.triggerType = pEvent->leafIdentity.triggerType;
  observation.openingTs = pEvent->leafIdentity.openingTs;
  observation.nativeDiscriminator = pEvent->leafIdentity.nativeDiscriminator;
  for (int32_t i = 0; i < taosArrayGetSize(pEvent->leafIdentity.lineage.pScopes); ++i) {
    const auto* pScope = static_cast<const SScopeInstanceId*>(taosArrayGet(pEvent->leafIdentity.lineage.pScopes, i));
    if (pScope == nullptr) return false;
    observation.lineage.push_back(*pScope);
  }
  observation.wstart = pEvent->calcParam.wstart;
  observation.wend = pEvent->calcParam.wend;
  observation.wduration = pEvent->calcParam.wduration;
  observation.wrownum = pEvent->calcParam.wrownum;
  observation.prevTs = pEvent->calcParam.prevTs;
  observation.currentTs = pEvent->calcParam.currentTs;
  observation.nextTs = pEvent->calcParam.nextTs;
  observation.triggerTime = pEvent->calcParam.triggerTime;
  observation.notifyType = pEvent->calcParam.notifyType;
  observation.contextPolicy = pEvent->contextPolicy;
  for (int32_t i = 0; i < taosArrayGetSize(pEvent->pSnapshots); ++i) {
    const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, i));
    if (pSnapshot == nullptr) return false;
    observation.snapshots.push_back({pSnapshot->layerIndex, pSnapshot->triggerType, pSnapshot->placeholderMask,
                                     pSnapshot->values.window.start, pSnapshot->values.window.end,
                                     pSnapshot->values.window.duration, pSnapshot->values.window.rownum});
  }
  observation.rows = rows;
  std::sort(observation.rows.begin(), observation.rows.end(), observedScopedRowLess);
  *pObservation = std::move(observation);
  return true;
}

static bool captureHistoryCanonicalObservation(NestedHistoryHarness&       harness,
                                               CanonicalNestedObservation* pObservation) {
  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  if (pEvent == nullptr) return false;
  SStreamCacheScope              scope = {.gid = pEvent->leafIdentity.gid,
                                          .lineage = {.pScopes = pEvent->leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  return harness.readHistoryRows(scope, &rows) == TSDB_CODE_SUCCESS &&
         captureCanonicalNestedObservation(pEvent, rows, pObservation);
}

static bool captureNestedRouteRealtimeCanonicalObservation(NestedRouteRuntimeFixture&  harness,
                                                           CanonicalNestedObservation* pObservation) {
  const SSTriggerCalcRequest* pRequest = harness.latestCalc();
  if (pRequest == nullptr || pRequest->params == nullptr || taosArrayGetSize(pRequest->params) != 1 ||
      pRequest->pContextPolicy == nullptr || pRequest->pContextPolicy->pEntries == nullptr ||
      pRequest->pAncestorContext == nullptr || pRequest->pAncestorContext->pParamContexts == nullptr) {
    return false;
  }
  const auto*                        pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 0));
  const SStreamAncestorParamContext* pParamContext = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pRequest->pAncestorContext->pParamContexts); ++i) {
    const auto* pCandidate =
        static_cast<const SStreamAncestorParamContext*>(taosArrayGet(pRequest->pAncestorContext->pParamContexts, i));
    if (pCandidate != nullptr && pCandidate->paramIndex == 0) pParamContext = pCandidate;
  }
  const SStreamContextPolicyEntry* pPolicy = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pRequest->pContextPolicy->pEntries); ++i) {
    const auto* pCandidate =
        static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pRequest->pContextPolicy->pEntries, i));
    if (pCandidate != nullptr && pCandidate->paramIndex == 0) pPolicy = pCandidate;
  }
  if (pParam == nullptr || pParamContext == nullptr || pPolicy == nullptr) return false;

  SStreamNestedPendingCalcEvent event = {};
  event.calcParam = *pParam;
  event.contextPolicy = pPolicy->contextPolicy;
  event.leafIdentity = pParamContext->leafIdentity;
  event.pSnapshots = pParamContext->pSnapshots;
  std::vector<ObservedScopedRow> rows;
  return harness.readCommittedRows(*pParamContext, &rows) == TSDB_CODE_SUCCESS &&
         captureCanonicalNestedObservation(&event, rows, pObservation);
}

static bool captureRealtimeCalcCanonicalObservation(RealtimePipelineHarness&    harness,
                                                    CanonicalNestedObservation* pObservation) {
  PipelineCalcAttempt* pAttempt = harness.calcAttempt(0);
  if (pAttempt == nullptr || pAttempt->decoded.params == nullptr || taosArrayGetSize(pAttempt->decoded.params) != 1 ||
      pAttempt->decoded.pContextPolicy == nullptr || pAttempt->decoded.pContextPolicy->pEntries == nullptr ||
      pAttempt->decoded.pAncestorContext == nullptr || pAttempt->decoded.pAncestorContext->pParamContexts == nullptr) {
    return false;
  }
  const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pAttempt->decoded.params, 0));
  const SStreamAncestorParamContext* pParamContext = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pAttempt->decoded.pAncestorContext->pParamContexts); ++i) {
    const auto* pCandidate = static_cast<const SStreamAncestorParamContext*>(
        taosArrayGet(pAttempt->decoded.pAncestorContext->pParamContexts, i));
    if (pCandidate != nullptr && pCandidate->paramIndex == 0) pParamContext = pCandidate;
  }
  const SStreamContextPolicyEntry* pPolicy = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pAttempt->decoded.pContextPolicy->pEntries); ++i) {
    const auto* pCandidate =
        static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pAttempt->decoded.pContextPolicy->pEntries, i));
    if (pCandidate != nullptr && pCandidate->paramIndex == 0) pPolicy = pCandidate;
  }
  if (pParam == nullptr || pParamContext == nullptr || pPolicy == nullptr) return false;

  SStreamNestedPendingCalcEvent event = {};
  event.calcParam = *pParam;
  event.contextPolicy = pPolicy->contextPolicy;
  event.leafIdentity = pParamContext->leafIdentity;
  event.pSnapshots = pParamContext->pSnapshots;
  SStreamCacheScope scope = {.gid = event.leafIdentity.gid, .lineage = {.pScopes = event.leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  for (int32_t value : harness.readScope(scope)) rows.emplace_back(0, value);
  return captureCanonicalNestedObservation(&event, rows, pObservation);
}

static bool captureHistoryCalcCanonicalObservation(NestedHistoryHarness&             harness,
                                                   const CanonicalNestedObservation& expected,
                                                   CanonicalNestedObservation*       pObservation) {
  PipelineCalcAttempt* pAttempt = harness.calcAttempt(0);
  if (pAttempt == nullptr || pAttempt->decoded.params == nullptr || taosArrayGetSize(pAttempt->decoded.params) < 1 ||
      pAttempt->decoded.pContextPolicy == nullptr || pAttempt->decoded.pContextPolicy->pEntries == nullptr ||
      pAttempt->decoded.pAncestorContext == nullptr || pAttempt->decoded.pAncestorContext->pParamContexts == nullptr) {
    return false;
  }
  const SStreamAncestorParamContext* pParamContext = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pAttempt->decoded.pAncestorContext->pParamContexts); ++i) {
    const auto* pCandidate = static_cast<const SStreamAncestorParamContext*>(
        taosArrayGet(pAttempt->decoded.pAncestorContext->pParamContexts, i));
    if (pCandidate != nullptr && pCandidate->leafIdentity.gid == expected.gid &&
        pCandidate->leafIdentity.triggerType == expected.triggerType &&
        pCandidate->leafIdentity.openingTs == expected.openingTs &&
        pCandidate->leafIdentity.nativeDiscriminator == expected.nativeDiscriminator) {
      if (pParamContext != nullptr) return false;
      pParamContext = pCandidate;
    }
  }
  if (pParamContext == nullptr) return false;
  const auto* pParam =
      static_cast<const SSTriggerCalcParam*>(taosArrayGet(pAttempt->decoded.params, pParamContext->paramIndex));
  const SStreamContextPolicyEntry* pPolicy = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pAttempt->decoded.pContextPolicy->pEntries); ++i) {
    const auto* pCandidate =
        static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pAttempt->decoded.pContextPolicy->pEntries, i));
    if (pCandidate != nullptr && pCandidate->paramIndex == pParamContext->paramIndex) pPolicy = pCandidate;
  }
  if (pParam == nullptr || pParamContext == nullptr || pPolicy == nullptr) return false;

  SStreamNestedPendingCalcEvent event = {};
  event.calcParam = *pParam;
  event.contextPolicy = pPolicy->contextPolicy;
  event.leafIdentity = pParamContext->leafIdentity;
  event.pSnapshots = pParamContext->pSnapshots;
  SStreamCacheScope scope = {.gid = event.leafIdentity.gid, .lineage = {.pScopes = event.leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  return harness.readHistoryRows(scope, &rows, pParam->wstart, pParam->wend) == TSDB_CODE_SUCCESS &&
         captureCanonicalNestedObservation(&event, rows, pObservation);
}

static void expectCanonicalNestedObservationEqual(const CanonicalNestedObservation& expected,
                                                  const CanonicalNestedObservation& actual) {
  EXPECT_EQ(expected.gid, actual.gid);
  EXPECT_EQ(expected.triggerType, actual.triggerType);
  EXPECT_EQ(expected.openingTs, actual.openingTs);
  EXPECT_EQ(expected.nativeDiscriminator, actual.nativeDiscriminator);
  ASSERT_EQ(expected.lineage.size(), actual.lineage.size());
  for (size_t i = 0; i < expected.lineage.size(); ++i) {
    EXPECT_EQ(expected.lineage[i].layerIndex, actual.lineage[i].layerIndex);
    EXPECT_EQ(expected.lineage[i].triggerType, actual.lineage[i].triggerType);
    EXPECT_EQ(expected.lineage[i].openingTs, actual.lineage[i].openingTs);
    EXPECT_EQ(expected.lineage[i].nativeDiscriminator, actual.lineage[i].nativeDiscriminator);
  }
  EXPECT_EQ(expected.wstart, actual.wstart);
  EXPECT_EQ(expected.wend, actual.wend);
  EXPECT_EQ(expected.wduration, actual.wduration);
  EXPECT_EQ(expected.wrownum, actual.wrownum);
  EXPECT_EQ(expected.prevTs, actual.prevTs);
  EXPECT_EQ(expected.currentTs, actual.currentTs);
  EXPECT_EQ(expected.nextTs, actual.nextTs);
  EXPECT_EQ(expected.notifyType, actual.notifyType);
  EXPECT_EQ(expected.contextPolicy, actual.contextPolicy);
  EXPECT_EQ(expected.snapshots, actual.snapshots);
  EXPECT_EQ(expected.rows, actual.rows);
}

struct NestedHistoryTerminalProbe {
  Stub                                                      stub;
  int32_t                                                   frontierCalls = 0;
  int32_t                                                   tailCalls = 0;
  int32_t                                                   tailCommitCalls = 0;
  std::vector<std::pair<const SWindowChainState*, int64_t>> preparedTailGids;
  std::vector<const SWindowChainState*>                     committedTailStates;
  std::vector<int64_t>                                      tailCommitGids;
  bool                                                      failPrepareForCommittedState = false;
  int32_t                                                   committedPrepareFailures = 0;
  int32_t                                                   tailCandidates = 0;
  int64_t                                                   tailAncestorRows = -1;
  TSKEY                                                     tailAncestorStart = INT64_MIN;
  TSKEY                                                     tailAncestorEnd = INT64_MIN;
};

static NestedHistoryTerminalProbe* gNestedHistoryTerminalProbe = nullptr;

static int32_t captureNestedHistoryFrontier(SWindowChainState* pState, TSKEY frontier, int64_t nowNs,
                                            SArray* pCandidates) {
  NestedHistoryTerminalProbe* pProbe = gNestedHistoryTerminalProbe;
  ++pProbe->frontierCalls;
  pProbe->stub.reset(stWindowChainAdvanceFrontier);
  int32_t code = stWindowChainAdvanceFrontier(pState, frontier, nowNs, pCandidates);
  pProbe->stub.set(stWindowChainAdvanceFrontier, captureNestedHistoryFrontier);
  return code;
}

static int32_t captureNestedHistoryTail(const SWindowChainState* pState, int64_t nowNs, SArray* pCandidates) {
  NestedHistoryTerminalProbe* pProbe = gNestedHistoryTerminalProbe;
  ++pProbe->tailCalls;
  if (pProbe->failPrepareForCommittedState &&
      std::find(pProbe->committedTailStates.begin(), pProbe->committedTailStates.end(), pState) !=
          pProbe->committedTailStates.end()) {
    ++pProbe->committedPrepareFailures;
    return TSDB_CODE_OUT_OF_MEMORY;
  }
  pProbe->stub.reset(stWindowChainPrepareHistoryLeafTail);
  int32_t code = stWindowChainPrepareHistoryLeafTail(pState, nowNs, pCandidates);
  pProbe->stub.set(stWindowChainPrepareHistoryLeafTail, captureNestedHistoryTail);
  if (code != TSDB_CODE_SUCCESS || pCandidates == nullptr) return code;
  pProbe->tailCandidates = taosArrayGetSize(pCandidates);
  if (pProbe->tailCandidates > 0) {
    const auto* pCandidate = static_cast<const SLeafEventCandidate*>(taosArrayGet(pCandidates, 0));
    if (pCandidate != nullptr) pProbe->preparedTailGids.emplace_back(pState, pCandidate->instanceId.gid);
    if (pCandidate != nullptr && pCandidate->pAncestorSnapshots != nullptr &&
        taosArrayGetSize(pCandidate->pAncestorSnapshots) > 0) {
      const auto* pAncestor =
          static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pCandidate->pAncestorSnapshots, 0));
      if (pAncestor != nullptr) {
        pProbe->tailAncestorRows = pAncestor->values.window.rownum;
        pProbe->tailAncestorStart = pAncestor->values.window.start;
        pProbe->tailAncestorEnd = pAncestor->values.window.end;
      }
    }
  }
  return code;
}

static void captureNestedHistoryTailCommit(SWindowChainState* pState) {
  NestedHistoryTerminalProbe* pProbe = gNestedHistoryTerminalProbe;
  ++pProbe->tailCommitCalls;
  auto prepared = std::find_if(
      pProbe->preparedTailGids.rbegin(), pProbe->preparedTailGids.rend(),
      [pState](const std::pair<const SWindowChainState*, int64_t>& value) { return value.first == pState; });
  pProbe->tailCommitGids.push_back(prepared == pProbe->preparedTailGids.rend() ? INT64_MIN : prepared->second);
  pProbe->committedTailStates.push_back(pState);
  pProbe->stub.reset(stWindowChainCommitHistoryLeafTail);
  stWindowChainCommitHistoryLeafTail(pState);
  pProbe->stub.set(stWindowChainCommitHistoryLeafTail, captureNestedHistoryTailCommit);
}

class ScopedNestedHistoryTerminalProbe {
 public:
  ScopedNestedHistoryTerminalProbe() {
    gNestedHistoryTerminalProbe = &probe_;
    probe_.stub.set(stWindowChainAdvanceFrontier, captureNestedHistoryFrontier);
    probe_.stub.set(stWindowChainPrepareHistoryLeafTail, captureNestedHistoryTail);
    probe_.stub.set(stWindowChainCommitHistoryLeafTail, captureNestedHistoryTailCommit);
  }

  ~ScopedNestedHistoryTerminalProbe() {
    probe_.stub.reset(stWindowChainCommitHistoryLeafTail);
    probe_.stub.reset(stWindowChainPrepareHistoryLeafTail);
    probe_.stub.reset(stWindowChainAdvanceFrontier);
    gNestedHistoryTerminalProbe = nullptr;
  }

  const NestedHistoryTerminalProbe& get() const { return probe_; }
  void                              failPrepareForCommittedState() { probe_.failPrepareForCommittedState = true; }
  void                              stopFailingPrepareForCommittedState() {
    probe_.failPrepareForCommittedState = false;
    probe_.committedTailStates.clear();
  }
  void resetObservation() {
    probe_.frontierCalls = 0;
    probe_.tailCalls = 0;
    probe_.tailCommitCalls = 0;
    probe_.preparedTailGids.clear();
    probe_.committedTailStates.clear();
    probe_.tailCommitGids.clear();
    probe_.failPrepareForCommittedState = false;
    probe_.committedPrepareFailures = 0;
    probe_.tailCandidates = 0;
    probe_.tailAncestorRows = -1;
    probe_.tailAncestorStart = INT64_MIN;
    probe_.tailAncestorEnd = INT64_MIN;
  }

 private:
  NestedHistoryTerminalProbe probe_;
};

