constexpr int32_t NestedHistoryHarness::kOriginalNodeB;

static int64_t              gNestedHistoryCheckpointStreamId = 0;
static std::vector<uint8_t> gNestedHistoryCheckpointBytes;
static int32_t              captureNestedHistoryCheckpoint(int64_t streamId, void* pData, int64_t dataLen) {
  if (pData == nullptr || dataLen <= 0) return TSDB_CODE_INVALID_PARA;
  gNestedHistoryCheckpointStreamId = streamId;
  const auto* pBytes = static_cast<const uint8_t*>(pData);
  gNestedHistoryCheckpointBytes.assign(pBytes, pBytes + dataLen);
  return TSDB_CODE_SUCCESS;
}

