static void startNestedHistoryRangeRecalc(NestedHistoryHarness& harness, NestedHistoryPlan plan,
                                          const STimeWindow& calcRange, TSKEY scanEnd,
                                          bool partitionRowsPlaceholder = true) {
  ASSERT_TRUE(harness.deploy(plan, 0, NestedHistoryHarness::kScanStart - 1, false, 0, false, false, 2, false, true,
                             partitionRowsPlaceholder));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRealtimeWal(scanEnd, 99));
  SSTriggerRealtimeGroup* pRealtimeGroup = harness.realtimeGroup();
  ASSERT_NE(nullptr, pRealtimeGroup);
  STimeWindow requested = calcRange;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAddRecalcRequest(harness.task(), pRealtimeGroup, &requested, false, true, true, 0));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedHistoryStart());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
}

static void prepareNestedHistoryEffects(NestedHistoryHarness& harness, ESTriggerEventType calcEventType,
                                        ESTriggerEventType notifyEventType, bool notifyHistory,
                                        int32_t runnerReplicas = 2, bool partitionRowsPlaceholder = true) {
  ASSERT_TRUE(harness.deploy(NestedHistoryPlan::SessionCount, 0,
                             NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep,
                             notifyEventType != STRIGGER_EVENT_WINDOW_NONE, 0, true, notifyHistory, runnerReplicas,
                             false, true, partitionRowsPlaceholder));
  ASSERT_TRUE(harness.setHistoryEffectPolicy(calcEventType, notifyEventType, notifyHistory));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMeta());
}

static void prepareNestedHistoryGroups(NestedHistoryHarness& harness, int32_t groupCount, int32_t runnerReplicas,
                                       bool partitionRowsPlaceholder = true) {
  ASSERT_GT(groupCount, 0);
  ASSERT_TRUE(harness.deploy(NestedHistoryPlan::SessionUnitCount, 0,
                             NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep, false, 0, true,
                             false, runnerReplicas, false, true, partitionRowsPlaceholder));
  ASSERT_TRUE(harness.setHistoryEffectPolicy(STRIGGER_EVENT_WINDOW_CLOSE, STRIGGER_EVENT_WINDOW_NONE, false));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());

  std::vector<NestedHistoryMetaRow> metas;
  metas.reserve(groupCount);
  for (int32_t i = 0; i < groupCount; ++i) {
    metas.emplace_back(NestedHistoryHarness::kScanStart, NestedHistoryHarness::kScanStart,
                       NestedHistoryHarness::kTableUid + i, 1, NestedHistoryHarness::kGid + i);
  }
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas(metas));
  for (int32_t i = 0; i < groupCount; ++i) {
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondRowsFor(NestedHistoryHarness::kTableUid + i, {NestedHistoryHarness::kScanStart}, {i + 1}));
  }
}

static int32_t dispatchHistoryGroupColValue(NestedHistoryHarness& harness, int64_t gid) {
  SSTriggerHistoryContext* pContext = harness.historyContext();
  if (pContext == nullptr) return TSDB_CODE_INVALID_PARA;

  SSTriggerGroupColValueRequest request = {};
  request.base.type = STRIGGER_PULL_GROUP_COL_VALUE;
  request.base.sessionId = NestedHistoryHarness::kHistorySession;
  request.gid = gid;
  SSTriggerAHandle ahandle = {};
  ahandle.param = &request;
  SMsgSendInfo sendInfo = {};
  sendInfo.param = &ahandle;
  SRpcMsg response = {.msgType = TDMT_STREAM_TRIGGER_PULL_RSP, .code = TSDB_CODE_SUCCESS};
  response.info.ahandle = &sendInfo;

  const ESTriggerContextStatus previousStatus = pContext->status;
  pContext->status = STRIGGER_CONTEXT_SEND_CALC_REQ;
  int64_t errorTaskId = 0;
  int32_t code = stTriggerTaskProcessRsp(&harness.task()->task, &response, &errorTaskId);
  pContext->status = previousStatus;
  return code;
}

static void expectNestedHistoryEffects(NestedHistoryHarness& harness, int32_t expectedCachedRows,
                                       int32_t expectedPending, int32_t expectedNotifyType, int32_t expectedNoticeCount,
                                       int32_t expectedCalcAttempts) {
  SSTriggerHistoryGroup* pGroup = harness.historyGroup();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_EQ(expectedPending, listNEles(&pGroup->pendingNestedEvents));
  EXPECT_EQ(0, listNEles(&pGroup->pendingNestedParWinEvents));
  if (expectedPending > 0) {
    const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
    ASSERT_NE(nullptr, pEvent);
    EXPECT_EQ(expectedNotifyType, pEvent->calcParam.notifyType);
  }

  std::vector<ObservedScopedRow> cachedRows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readOuterSessionRows(&cachedRows));
  EXPECT_EQ(expectedCachedRows, static_cast<int32_t>(cachedRows.size()));

  EXPECT_EQ(expectedNoticeCount, static_cast<int32_t>(gNestedOutboxPayloads.size()));
  EXPECT_EQ(expectedCalcAttempts, harness.calcAttemptCount());
}

TEST_F(StreamNestedHistoryEquivalenceTest, NormalRealtimeHistoryAndRecalcMatch) {
  CanonicalNestedObservation                 realtime;
  CanonicalNestedObservation                 history;
  CanonicalNestedObservation                 historyRequest;
  CanonicalNestedObservation                 recalc;
  std::vector<NestedHistoryPeerSubmitRecord> historySubmits;
  std::vector<NestedHistoryPeerSubmitRecord> recalcSubmits;

  {
    RealtimePipelineHarness harness;
    harness.enableNestedValueCacheProjection();
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_CLOSE,
                             STRIGGER_EVENT_WINDOW_NONE, 0, 1, true));
    harness.retainCalcAttempts();
    ASSERT_TRUE(harness.start());
    ASSERT_TRUE(harness.feedRows({1000, 1015}, {10, 20}));
    ASSERT_TRUE(harness.respondCalcRows({1000, 1015}, {10, 20}));
    ASSERT_TRUE(captureRealtimeCalcCanonicalObservation(harness, &realtime));
  }

  {
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deploy(NestedHistoryPlan::SessionSession));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
    ScopedNestedHistoryPeerRegistrationProbe peerProbe;
    Stub                                     sorterStub;
    NestedHistoryPinningProbe                sorterProbe;
    sorterProbe.pHarness = &harness;
    gNestedHistoryPinningStub = &sorterStub;
    gNestedHistoryPinningProbe = &sorterProbe;
    sorterStub.set(stTimestampSorterNextDataBlock, captureNestedHistorySorterNext);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1015, NestedHistoryHarness::kTableUid, 2}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1015}, {10, 20}));
    sorterStub.reset(stTimestampSorterNextDataBlock);
    gNestedHistoryPinningProbe = nullptr;
    gNestedHistoryPinningStub = nullptr;
    EXPECT_GT(sorterProbe.sorterNextCalls, 0);
    ASSERT_TRUE(captureHistoryCanonicalObservation(harness, &history));
    historySubmits = peerProbe.get().submits;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcDataRows({1000, 1015}, {10, 20}));
    ASSERT_EQ(1, harness.calcAttemptCount());
    ASSERT_TRUE(captureHistoryCalcCanonicalObservation(harness, history, &historyRequest));
    history = historyRequest;
  }

  {
    NestedHistoryHarness harness;
    startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionSession, {1000, 1000},
                                  NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep);
    ScopedNestedHistoryPeerRegistrationProbe peerProbe;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1015, NestedHistoryHarness::kTableUid, 2}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1015}, {10, 20}));
    EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));
    recalcSubmits = peerProbe.get().submits;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcDataRows({1000, 1015}, {10, 20}));
    ASSERT_EQ(1, harness.calcAttemptCount());
    ASSERT_TRUE(captureHistoryCalcCanonicalObservation(harness, history, &recalc));
  }

  expectCanonicalNestedObservationEqual(realtime, history);
  expectCanonicalNestedObservationEqual(history, recalc);
  expectCanonicalNestedObservationEqual(realtime, historyRequest);
  expectCanonicalNestedObservationEqual(historyRequest, recalc);
  EXPECT_GT(realtime.triggerTime, 0);
  EXPECT_GT(history.triggerTime, 0);
  EXPECT_GT(historyRequest.triggerTime, 0);
  EXPECT_GT(recalc.triggerTime, 0);
  ASSERT_FALSE(historySubmits.empty());
  EXPECT_EQ(historySubmits, recalcSubmits);
}

static int32_t driveVirtualHistoryRows(NestedHistoryHarness& harness) {
  int32_t code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {});
  if (code != TSDB_CODE_SUCCESS) return code;
  code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {});
  if (code != TSDB_CODE_SUCCESS) return code;
  code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                             {{1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1}});
  if (code != TSDB_CODE_SUCCESS) return code;
  code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                             {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}});
  if (code != TSDB_CODE_SUCCESS) return code;
  for (int32_t source = 0; source < 2; ++source) {
    CapturedPullAttempt* pData = harness.findVirtualDataPull();
    if (pData == nullptr) return TSDB_CODE_INTERNAL_ERROR;
    const int64_t physicalUid = pData->request.value().tsdbDataReq.uid;
    code = harness.respondVirtualRows(*pData, 1000, physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202);
    if (code != TSDB_CODE_SUCCESS) return code;
  }
  return TSDB_CODE_SUCCESS;
}

TEST_F(StreamNestedHistoryEquivalenceTest, VirtualRealtimeHistoryAndRecalcMatch) {
  CanonicalNestedObservation realtime;
  CanonicalNestedObservation history;
  CanonicalNestedObservation historyRequest;
  CanonicalNestedObservation recalc;

  {
    NestedRouteRuntimeFixture harness;
    ASSERT_TRUE(harness.deployNestedVirtualPair(2, 2, NestedHistoryHarness::kVirtualUidA,
                                                NestedHistoryHarness::kVirtualUidB, STRIGGER_EVENT_WINDOW_NONE));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(2));
    CapturedPullAttempt* pSourceA = harness.findNestedAttempt(0);
    CapturedPullAttempt* pSourceB = harness.findNestedAttempt(1);
    ASSERT_NE(nullptr, pSourceA);
    ASSERT_NE(nullptr, pSourceB);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pSourceA, NestedRouteRuntimeFixture::kEventTs, 101));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pSourceB, NestedRouteRuntimeFixture::kEventTs, 202));
    ASSERT_EQ(1, harness.calcSendCount());
    ASSERT_TRUE(captureNestedRouteRealtimeCanonicalObservation(harness, &realtime));
  }

  {
    ExistingMergerProbe  probe;
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
    ASSERT_EQ(TSDB_CODE_SUCCESS, driveVirtualHistoryRows(harness));
    ASSERT_TRUE(captureHistoryCanonicalObservation(harness, &history));
    EXPECT_GT(probe.count(ExistingMergerCall::SetMergeInfo), 0);
    EXPECT_GT(probe.count(ExistingMergerCall::GetMetaToFetch), 0);
    EXPECT_GT(probe.count(ExistingMergerCall::BindDataBlock), 0);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    ASSERT_EQ(1, harness.calcAttemptCount());
    ASSERT_TRUE(captureHistoryCalcCanonicalObservation(harness, history, &historyRequest));
  }

  {
    ExistingMergerProbe  probe;
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual(NestedHistoryHarness::kScanStart - 1, false, false));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    SSTriggerRealtimeGroup recalcGroup = {};
    recalcGroup.gid = NestedHistoryHarness::kGid;
    recalcGroup.newThreshold = 1000;
    STimeWindow requested = {.skey = 1000, .ekey = 1000};
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              stTriggerTaskAddRecalcRequest(harness.task(), &recalcGroup, &requested, false, true, true, 0));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedHistoryStart());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
    ASSERT_EQ(TSDB_CODE_SUCCESS, driveVirtualHistoryRows(harness));
    EXPECT_GT(probe.count(ExistingMergerCall::SetMergeInfo), 0);
    EXPECT_GT(probe.count(ExistingMergerCall::GetMetaToFetch), 0);
    EXPECT_GT(probe.count(ExistingMergerCall::BindDataBlock), 0);
    ASSERT_EQ(1, harness.calcAttemptCount());
    ASSERT_TRUE(captureHistoryCalcCanonicalObservation(harness, history, &recalc));
  }

  expectCanonicalNestedObservationEqual(realtime, history);
  expectCanonicalNestedObservationEqual(history, recalc);
  expectCanonicalNestedObservationEqual(realtime, historyRequest);
  expectCanonicalNestedObservationEqual(historyRequest, recalc);
  EXPECT_GT(realtime.triggerTime, 0);
  EXPECT_GT(history.triggerTime, 0);
  EXPECT_GT(historyRequest.triggerTime, 0);
  EXPECT_GT(recalc.triggerTime, 0);
}

TEST_F(StreamNestedHistoryEffectsTest, ScanPrefixUpdatesLocalStateOnly) {
  NestedHistoryHarness harness;
  startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionCount, {1002, 1002},
                                NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetaAt(1000, NestedHistoryHarness::kTableUid, 2));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1000}, {10, 20}));

  SSTriggerHistoryGroup* pGroup = harness.historyGroup();
  ASSERT_NE(nullptr, pGroup);
  EXPECT_EQ(0, listNEles(&pGroup->pendingNestedEvents));
  EXPECT_EQ(0, listNEles(&pGroup->pendingNestedParWinEvents));

  SScopeInstanceId outerScope = {
      .layerIndex = 0,
      .triggerType = WINDOW_TYPE_SESSION,
      .openingTs = 1000,
      .nativeDiscriminator = 0,
  };
  SStreamCacheScope scope = {
      .gid = NestedHistoryHarness::kGid,
      .lineage = {.pScopes = taosArrayInit(1, sizeof(outerScope))},
  };
  ASSERT_NE(nullptr, scope.lineage.pScopes);
  ASSERT_NE(nullptr, taosArrayPush(scope.lineage.pScopes, &outerScope));
  std::vector<ObservedScopedRow> cachedRows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &cachedRows));
  EXPECT_TRUE(cachedRows.empty());
  taosArrayDestroy(scope.lineage.pScopes);

  EXPECT_TRUE(gNestedOutboxPayloads.empty());
}

