TEST_F(StreamNestedHistoryRangeTest, PureSlidingUsesPrevAndCurrentTsForEligibility) {
  NestedHistoryHarness                     harness;
  ScopedNestedHistoryPeerRegistrationProbe peerProbe;
  startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::PureSliding, {1500, 1500},
                                NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 2000, NestedHistoryHarness::kTableUid, 2}}));
  Stub stageStub;
  gNestedHistoryPendingNodeStub = &stageStub;
  gNestedHistoryPendingNodeCalls = 0;
  gNestedHistoryPendingNodeFailureCall = INT32_MAX;
  gNestedHistoryPendingNodeGids.clear();
  stageStub.set(stAllocNestedPendingCalcNode, failSelectedNestedHistoryPendingNode);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 2000}, {10, 20}));
  EXPECT_EQ(1, gNestedHistoryPendingNodeCalls);
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kGid}), gNestedHistoryPendingNodeGids);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
  stageStub.reset(stAllocNestedPendingCalcNode);
  gNestedHistoryPendingNodeStub = nullptr;

  std::vector<NestedHistoryCandidateRecord> candidates;
  for (const auto& submit : peerProbe.get().submits) {
    candidates.insert(candidates.end(), submit.candidates.begin(), submit.candidates.end());
  }
  auto eligible = std::find_if(candidates.begin(), candidates.end(), [](const NestedHistoryCandidateRecord& candidate) {
    return candidate.prevTs <= 1500 && candidate.currentTs >= 1500;
  });
  ASSERT_NE(candidates.end(), eligible);
  EXPECT_EQ(1001, eligible->prevTs);
  EXPECT_EQ(2000, eligible->currentTs);
  EXPECT_EQ(2, gNestedHistoryPendingNodeCalls);
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kGid, NestedHistoryHarness::kGid}),
            gNestedHistoryPendingNodeGids);
}

