  auto*         pRequestingMerger = probe.mergerForPhysicalUid(physicalUid);
  ASSERT_NE(nullptr, pRequestingMerger);
  EXPECT_EQ(0, probe.count(ExistingMergerCall::BindDataBlock, pRequestingMerger));

  const TSKEY timestamp = physicalUid == NestedHistoryHarness::kPhysicalUidA ? NestedHistoryHarness::kScanStart
                                                                             : NestedHistoryHarness::kScanStart + 1;
