TEST_F(StreamNestedHistoryNormalTest, PeerCommitDoesNotEagerlyMaterializeTrows) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deploy());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());

  Stub                      pinningStub;
  NestedHistoryPinningProbe probe;
  probe.pHarness = &harness;
  gNestedHistoryPinningStub = &pinningStub;
  gNestedHistoryPinningProbe = &probe;
  pinningStub.set(stTimestampSorterNextDataBlock, captureNestedHistorySorterNext);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1000, NestedHistoryHarness::kTableUid, 1},
                                                     {1000, 1000, NestedHistoryHarness::kSecondTableUid, 1}}));

  int32_t finalResponseCode = TSDB_CODE_SUCCESS;
  for (int32_t source = 0; source < 2; ++source) {
    CapturedPullAttempt* pAttempt = harness.pendingDataPull();
    ASSERT_NE(nullptr, pAttempt);
    const int64_t uid = pAttempt->request.value().tsdbTsDataReq.uid;
    finalResponseCode = harness.respondRowsFor(uid, {1000}, {uid == NestedHistoryHarness::kTableUid ? 10 : 20});
    ASSERT_EQ(TSDB_CODE_SUCCESS, finalResponseCode);
  }
  pinningStub.reset(stTimestampSorterNextDataBlock);
  gNestedHistoryPinningProbe = nullptr;
  gNestedHistoryPinningStub = nullptr;

  EXPECT_EQ(0, probe.commitCalls);
  EXPECT_GT(probe.sorterNextCalls, 0);
  EXPECT_FALSE(probe.nextCalledInsideCommit);

  SSTriggerHistoryGroup* pGroup = harness.historyGroup();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_EQ(1, listNEles(&pGroup->pendingNestedEvents));
  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  SStreamCacheScope              scope = {.gid = pEvent->leafIdentity.gid,
                                          .lineage = {.pScopes = pEvent->leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
  EXPECT_TRUE(rows.empty());
  EXPECT_EQ(nullptr, pGroup->pPeerMerger);
  EXPECT_EQ(nullptr, pGroup->pNestedPeerSources);
}

