TEST_F(StreamNestedHistoryNormalTest, ResponseBindsRequestingSource) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deploy());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1000, NestedHistoryHarness::kTableUid, 1},
                                                     {1001, 1001, NestedHistoryHarness::kSecondTableUid, 1}}));

  CapturedPullAttempt* pFirstAttempt = harness.pendingDataPull();
  ASSERT_NE(nullptr, pFirstAttempt);
  const uintptr_t firstRequestAddress = NestedHistoryHarness::requestAddress(*pFirstAttempt);
  const int64_t   firstUid = pFirstAttempt->request.value().tsdbTsDataReq.uid;
  const TSKEY     firstTs = firstUid == NestedHistoryHarness::kTableUid ? 1000 : 1001;
  ASSERT_NE(0U, firstRequestAddress);
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRowsFor(firstUid, {firstTs}, {firstUid == NestedHistoryHarness::kTableUid ? 10 : 20}));

  CapturedPullAttempt* pSecondAttempt = harness.pendingDataPull();
  ASSERT_NE(nullptr, pSecondAttempt);
  const uintptr_t secondRequestAddress = NestedHistoryHarness::requestAddress(*pSecondAttempt);
  const int64_t   secondUid = pSecondAttempt->request.value().tsdbTsDataReq.uid;
  const TSKEY     secondTs = secondUid == NestedHistoryHarness::kTableUid ? 1000 : 1001;
  EXPECT_NE(firstRequestAddress, secondRequestAddress);
  ASSERT_NE(firstUid, secondUid);
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRowsFor(secondUid, {secondTs}, {secondUid == NestedHistoryHarness::kTableUid ? 10 : 20}));

  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  EXPECT_EQ(1000, pEvent->calcParam.wstart);
  EXPECT_EQ(1001, pEvent->calcParam.wend);
  SStreamCacheScope              scope = {.gid = pEvent->leafIdentity.gid,
                                          .lineage = {.pScopes = pEvent->leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
  EXPECT_TRUE(rows.empty());
}

