TEST_F(StreamNestedHistoryEquivalenceTest, PermutingSourcesPreservesIdentitySnapshotAndRows) {
  auto runScenario = [](bool reverseLogicalOrder, bool secondSourceOnNextPage, CanonicalNestedObservation* pObservation,
                        std::vector<NestedHistoryPeerSubmitRecord>* pSubmits, std::vector<int64_t>* pRegistrationOrder,
                        std::array<int32_t, 3>* pMergerCounts) {
    ExistingMergerProbe  mergerProbe;
    NestedHistoryHarness harness;
    if (!harness.deployVirtual()) return TSDB_CODE_INTERNAL_ERROR;
    int32_t code = harness.driveVirtualDiscovery(reverseLogicalOrder);
    if (code != TSDB_CODE_SUCCESS) return code;
    code = harness.startHistoryRequest();
    if (code != TSDB_CODE_SUCCESS) return code;
    code = harness.respondAllVirtualFirstTs();
    if (code != TSDB_CODE_SUCCESS) return code;
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

    code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {});
    if (code != TSDB_CODE_SUCCESS) return code;
    code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {});
    if (code != TSDB_CODE_SUCCESS) return code;
    if (!secondSourceOnNextPage) {
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                 {{1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1}});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                 {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}});
    } else {
      std::vector<NestedHistoryMetaRow> firstPage;
      firstPage.reserve(STREAM_RETURN_ROWS_NUM);
      firstPage.push_back({1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1});
      for (int32_t row = 1; row < STREAM_RETURN_ROWS_NUM; ++row) {
        firstPage.push_back({1000, 1000, 900000 + row, 1});
      }
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA, firstPage);
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskA, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskB, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskA, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                     {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}});
    }
    if (code != TSDB_CODE_SUCCESS) return code;

    for (int32_t source = 0; source < 2; ++source) {
      CapturedPullAttempt* pData = harness.findVirtualDataPull();
      if (pData == nullptr) return TSDB_CODE_INTERNAL_ERROR;
      const int64_t physicalUid = pData->request.value().tsdbDataReq.uid;
      code = harness.respondVirtualRows(*pData, 1000, physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202);
      if (code != TSDB_CODE_SUCCESS) return code;
    }

    if (!captureHistoryCanonicalObservation(harness, pObservation)) return TSDB_CODE_INTERNAL_ERROR;
    *pSubmits = registrationProbe.get().submits;
    if (registrationProbe.get().roundTableUids.size() != 1) return TSDB_CODE_INTERNAL_ERROR;
    *pRegistrationOrder = registrationProbe.get().roundTableUids[0];
    *pMergerCounts = {{mergerProbe.count(ExistingMergerCall::SetMergeInfo),
                       mergerProbe.count(ExistingMergerCall::GetMetaToFetch),
                       mergerProbe.count(ExistingMergerCall::BindDataBlock)}};
    return TSDB_CODE_SUCCESS;
  };

  CanonicalNestedObservation                 baseline;
  std::vector<NestedHistoryPeerSubmitRecord> baselineSubmits;
  std::vector<int64_t>                       baselineRegistration;
  std::array<int32_t, 3>                     baselineMergerCounts = {};
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            runScenario(false, false, &baseline, &baselineSubmits, &baselineRegistration, &baselineMergerCounts));
  EXPECT_EQ(1000, baseline.wstart);
  EXPECT_EQ(1000, baseline.wend);
  EXPECT_EQ(2, baseline.wrownum);
  ASSERT_EQ(1U, baseline.snapshots.size());
  EXPECT_EQ(1000, baseline.snapshots[0][3]);
  EXPECT_EQ(1000, baseline.snapshots[0][4]);
  EXPECT_EQ(2, baseline.snapshots[0][6]);
  EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidA, 101},
                                            {NestedHistoryHarness::kVirtualUidB, 202}}),
            baseline.rows);
  EXPECT_GT(baseline.triggerTime, 0);
  for (int32_t count : baselineMergerCounts) EXPECT_GT(count, 0);
  ASSERT_EQ(1U, baselineSubmits.size());
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA, NestedHistoryHarness::kVirtualUidB}),
            baselineSubmits[0].tableUids);
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidB, NestedHistoryHarness::kVirtualUidA}),
            baselineRegistration);

  for (bool reverseLogicalOrder : {false, true}) {
    for (bool secondSourceOnNextPage : {false, true}) {
      if (!reverseLogicalOrder && !secondSourceOnNextPage) continue;
      CanonicalNestedObservation                 observation;
      std::vector<NestedHistoryPeerSubmitRecord> submits;
      std::vector<int64_t>                       registrationOrder;
      std::array<int32_t, 3>                     mergerCounts = {};
      ASSERT_EQ(TSDB_CODE_SUCCESS, runScenario(reverseLogicalOrder, secondSourceOnNextPage, &observation, &submits,
                                               &registrationOrder, &mergerCounts));
      EXPECT_EQ(reverseLogicalOrder
                    ? (std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA, NestedHistoryHarness::kVirtualUidB})
                    : (std::vector<int64_t>{NestedHistoryHarness::kVirtualUidB, NestedHistoryHarness::kVirtualUidA}),
                registrationOrder);
      expectCanonicalNestedObservationEqual(baseline, observation);
      EXPECT_GT(observation.triggerTime, 0);
      EXPECT_EQ(baselineSubmits, submits);
      EXPECT_EQ(baselineMergerCounts, mergerCounts);
    }
  }
}

TEST_F(StreamNestedHistoryPeerTest, LateAddSourceFailsBeforeChainMutation) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deployVirtual());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
  ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
  std::vector<NestedHistoryMetaRow> firstPage;
  firstPage.reserve(STREAM_RETURN_ROWS_NUM);
  firstPage.push_back({1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1});
  for (int32_t row = 1; row < STREAM_RETURN_ROWS_NUM; ++row) {
    firstPage.push_back({1000, 1000, 910000 + row, 1});
  }
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA, firstPage));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskA, {}));

  EXPECT_TRUE(registrationProbe.get().addedTableUids.empty());
  EXPECT_EQ(0, registrationProbe.get().nextCalls);
  EXPECT_EQ(nullptr, harness.findVirtualDataPull());
  EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));

  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                    {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}}));
  EXPECT_FALSE(registrationProbe.get().addAfterNext);
  EXPECT_EQ(2, registrationProbe.get().firstNextSourceCount);

  SSTriggerHistoryGroup* pGroup = harness.historyGroup();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_NE(nullptr, registrationProbe.get().pStartedMerger);
  ASSERT_EQ(registrationProbe.get().pStartedMerger, pGroup->pPeerMerger);
  SWindowChainState*                pChainBefore = pGroup->pWindowChain;
  const int32_t                     sourcesBefore = taosArrayGetSize(pGroup->pNestedPeerSources);
  const int32_t                     eventsBefore = listNEles(&pGroup->pendingNestedEvents);
  const auto                        submitsBefore = registrationProbe.get().submits;
  int32_t                           dummySource = 0;
  const SStreamTriggerPeerSourceOps lateOps = {.peek = nestedHistoryLateSourcePeek,
                                               .consume = nestedHistoryLateSourceConsume};
  EXPECT_EQ(TSDB_CODE_INVALID_PARA,
            stTriggerMergerPeerAddSource(registrationProbe.get().pStartedMerger, 999999, &lateOps, &dummySource));
  EXPECT_EQ(pChainBefore, pGroup->pWindowChain);
  EXPECT_EQ(sourcesBefore, taosArrayGetSize(pGroup->pNestedPeerSources));
  EXPECT_EQ(eventsBefore, listNEles(&pGroup->pendingNestedEvents));
  EXPECT_EQ(submitsBefore, registrationProbe.get().submits);
  EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));

  for (int32_t source = 0; source < 2; ++source) {
    CapturedPullAttempt* pData = harness.findVirtualDataPull();
    ASSERT_NE(nullptr, pData);
    const int64_t physicalUid = pData->request.value().tsdbDataReq.uid;
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualRows(*pData, 1000, physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202));
  }
  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  EXPECT_EQ(2, pEvent->calcParam.wrownum);
  ASSERT_NE(nullptr, pEvent->pSnapshots);
  const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
  ASSERT_NE(nullptr, pSnapshot);
  EXPECT_EQ(2, pSnapshot->values.window.rownum);
  ASSERT_EQ(1U, registrationProbe.get().submits.size());
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA, NestedHistoryHarness::kVirtualUidB}),
            registrationProbe.get().submits[0].tableUids);
  SStreamCacheScope              scope = {.gid = pEvent->leafIdentity.gid,
                                          .lineage = {.pScopes = pEvent->leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
  std::sort(rows.begin(), rows.end(), observedScopedRowLess);
  EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidA, 101},
                                            {NestedHistoryHarness::kVirtualUidB, 202}}),
            rows);
}

