  ASSERT_NE(nullptr, pFreshGroup);
  EXPECT_NE(nullptr, pFreshGroup->pWindowChain);
  EXPECT_EQ(0, listNEles(&pFreshGroup->pendingNestedEvents));
  EXPECT_EQ(0, listNEles(&pFreshGroup->pendingNestedParWinEvents));
  EXPECT_EQ(nullptr, pFreshGroup->pPeerMerger);
  EXPECT_EQ(nullptr, pFreshGroup->pNestedPeerSources);
  std::vector<ObservedScopedRow> freshRows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readOuterSessionRows(&freshRows));
  EXPECT_TRUE(freshRows.empty());

  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondMetaAt(NestedHistoryHarness::kHistoryStep, NestedHistoryHarness::kTableUid, 1));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({NestedHistoryHarness::kHistoryStep}, {30}));
