TEST_F(StreamNestedRealtimeTest, LegacyEventParityExpressionsEvaluateEncodedSlots) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::LegacyParityEvent, false, STRIGGER_EVENT_WINDOW_NONE,
                           STRIGGER_EVENT_WINDOW_NONE));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedParityRows({
      {1000, false, 0, 1, 0},
      {2000, false, 0, 2, 7},
      {3000, false, 0, 3, 0},
      {4000, false, 0, 0, 2},
  }));

  const SSDataBlock* pBlock = harness.triggerBlock();
  ASSERT_NE(nullptr, pBlock);
  ASSERT_GE(blockDataGetNumOfCols(pBlock), 2);
  const auto* pEnd = static_cast<const SColumnInfoData*>(taosArrayGetLast(pBlock->pDataBlock));
  const auto* pStart = pEnd - 1;
  ASSERT_EQ(4, blockDataGetNumOfRows(pBlock));
  const std::array<uint8_t, 4> expectedStart = {1, 2, 3, 0};
  const std::array<uint8_t, 4> expectedEnd = {0, 1, 0, 1};
  for (int32_t row = 0; row < blockDataGetNumOfRows(pBlock); ++row) {
    EXPECT_EQ(expectedStart[row], *reinterpret_cast<const uint8_t*>(colDataGetData(pStart, row)));
    EXPECT_EQ(expectedEnd[row], *reinterpret_cast<const uint8_t*>(colDataGetData(pEnd, row)));
  }
}

TEST_F(StreamNestedRealtimeTest, DataDrivenLeavesMatchLegacySingleWindowRuntime) {
  struct LegacyParityCase {
    const char*              name;
    int8_t                   leafType;
    int64_t                  eventTypes;
    RealtimePipelinePlan     legacyPlan;
    RealtimePipelinePlan     nestedPlan;
    std::vector<PipelineRow> rows;
  };

  const std::array<LegacyParityCase, 3> cases = {{
      {"STATE",
       WINDOW_TYPE_STATE,
       STRIGGER_EVENT_WINDOW_OPEN | STRIGGER_EVENT_WINDOW_CLOSE,
       RealtimePipelinePlan::LegacyParityState,
       RealtimePipelinePlan::NestedParityState,
       {{1000, false, 7, 0, 0}, {2000, true, 0, 0, 0}, {3000, false, 8, 0, 0}, {4000, false, 8, 0, 0}}},
      {"COUNT",
       WINDOW_TYPE_COUNT,
       STRIGGER_EVENT_WINDOW_CLOSE,
       RealtimePipelinePlan::LegacyParityCount,
       RealtimePipelinePlan::NestedParityCount,
       {{1000, false, 0, 0, 0},
        {2000, false, 0, 0, 0},
        {3000, false, 0, 0, 0},
        {4000, false, 0, 0, 0},
        {5000, false, 0, 0, 0},
        {6000, false, 0, 0, 0}}},
      {"EVENT",
       WINDOW_TYPE_EVENT,
       STRIGGER_EVENT_WINDOW_OPEN | STRIGGER_EVENT_WINDOW_CLOSE,
       RealtimePipelinePlan::LegacyParityEvent,
       RealtimePipelinePlan::NestedParityEvent,
       {{1000, false, 0, 1, 0},
        {2000, false, 0, 1, 0},
        {3000, false, 0, 2, 0},
        {4000, false, 0, 3, 0},
        {5000, false, 0, 3, 0},
        {6000, false, 0, 0, 1}}},
  }};

  for (const auto& testCase : cases) {
    SCOPED_TRACE(testCase.name);
    LegacyParityHarness         harness;
    std::vector<ParityEmission> legacy;
    std::vector<ParityEmission> nested;
    ASSERT_TRUE(
        harness.capture(testCase.legacyPlan, testCase.leafType, testCase.eventTypes, testCase.rows, false, &legacy));
    ASSERT_FALSE(legacy.empty());
    ASSERT_TRUE(
        harness.capture(testCase.nestedPlan, testCase.leafType, testCase.eventTypes, testCase.rows, true, &nested));
    ASSERT_EQ(legacy.size(), nested.size());
    for (size_t emissionIndex = 0; emissionIndex < legacy.size(); ++emissionIndex) {
      SCOPED_TRACE(emissionIndex);
      EXPECT_NE(STRIGGER_EVENT_WINDOW_NONE, legacy[emissionIndex].notifyType);
      expectParityEmissionEqual(legacy[emissionIndex], nested[emissionIndex]);
    }
  }
}

