TEST_F(StreamNestedRealtimeTest, EofFrontierStageFailurePoisonsOwnerWithoutPublishingEffects) {
  NestedRouteRuntimeFixture harness;
  ASSERT_TRUE(harness.deployNestedVirtualPair(3, 3));
  harness.setFrontierTs(NestedRouteRuntimeFixture::kEventTs + 100);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(2));

  CapturedPullAttempt* pSource0 = harness.findNestedAttempt(0);
  ASSERT_NE(nullptr, pSource0);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pSource0, NestedRouteRuntimeFixture::kEventTs, 101));
  CapturedPullAttempt* pSource1 = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pSource1);

  SSTriggerRealtimeGroup* pGroup = harness.group();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_NE(nullptr, pGroup->pWindowChain);
  ASSERT_TRUE(pGroup->nestedInputRegistered);
  ASSERT_FALSE(pGroup->nestedInputFailed);
  ASSERT_EQ(0, listNEles(&pGroup->pendingNestedEvents));
  ASSERT_EQ(0, listNEles(&pGroup->pendingNestedParWinEvents));
  const uint64_t generationBeforeEof = pGroup->nestedInputGeneration;
  const int32_t  calcSendCountBeforeEof = harness.calcSendCount();
  int32_t        cachedRows = -1;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readOuterSessionRowCount(&cachedRows));
  ASSERT_EQ(0, cachedRows);

  {
    Stub stageStub;
    stageStub.set(stAllocNestedPendingCalcNode, failNestedPendingCalcNode);
    EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY, harness.respondBlock(*pSource1, NestedRouteRuntimeFixture::kEventTs, 202));
  }

  EXPECT_FALSE(pGroup->nestedInputRegistered);
  EXPECT_TRUE(pGroup->nestedInputFailed);
  EXPECT_FALSE(pGroup->nestedInputCancelled);
  EXPECT_NE(generationBeforeEof, pGroup->nestedInputGeneration);
  EXPECT_EQ(nullptr, pGroup->pWindowChain);
  EXPECT_EQ(0, listNEles(&pGroup->pendingNestedEvents));
  EXPECT_EQ(0, listNEles(&pGroup->pendingNestedParWinEvents));
  EXPECT_EQ(calcSendCountBeforeEof, harness.calcSendCount());
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.readOuterSessionRowCount(&cachedRows));
  EXPECT_EQ(0, cachedRows);

  bool noticePending = true;
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.confirmNoDeferredNotice(&noticePending));
  EXPECT_FALSE(noticePending);
  EXPECT_EQ(0, harness.noticeSendCount());

  EXPECT_EQ(TSDB_CODE_INTERNAL_ERROR, harness.dispatchSerializedRealtimeStart());
  EXPECT_EQ(nullptr, pGroup->pWindowChain);
  EXPECT_EQ(calcSendCountBeforeEof, harness.calcSendCount());
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.readOuterSessionRowCount(&cachedRows));
  EXPECT_EQ(0, cachedRows);
}

TEST_F(StreamNestedRealtimeTest, LegacyLowLatencyCalcDispatchesFromCreatingWalTurn) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::LegacySession, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, true));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedLastTsForReader(RealtimePipelineHarness::kReaderTaskId, 1000));

  Stub clockStub;
  clockStub.set(taosClockGetTime, captureRealtimePipelineTurnClock);
  const int64_t turnNow = 100000000;
  const int64_t calcParamNow = 102000000;
  resetRealtimePipelineTurnClock(turnNow, 1000000, turnNow);

  ASSERT_TRUE(harness.feedRows({1000, 2000}, {1, 2}));
  SSTriggerRealtimeGroup* pGroup = harness.group();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_NE(nullptr, harness.context());
  ASSERT_NE(nullptr, harness.context()->pMaxDelayHeap);
  ASSERT_EQ(1, harness.calcSendCount()) << "pending=" << pGroup->pPendingCalcParams.neles << " heapMinIsGroup="
                                        << (heapMin(harness.context()->pMaxDelayHeap) == &pGroup->heapNode)
                                        << " nextExecTime=" << pGroup->nextExecTime << " turnNow=" << turnNow
                                        << " calcParamNow=" << calcParamNow
                                        << " wallClockCalls=" << gRealtimePipelineTurnWallClockCalls;

  const SSTriggerCalcRequest* pRequest = harness.capturedCalc();
  ASSERT_NE(nullptr, pRequest);
  ASSERT_NE(nullptr, pRequest->params);
  ASSERT_EQ(1, taosArrayGetSize(pRequest->params));
  const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 0));
  ASSERT_NE(nullptr, pParam);
  EXPECT_EQ(calcParamNow, pParam->triggerTime);
  EXPECT_GT(pParam->triggerTime, turnNow);
  EXPECT_EQ(1000, pParam->wstart);
  EXPECT_EQ(1000, pParam->wend);
  EXPECT_EQ(1, pParam->wrownum);
}

TEST_F(StreamNestedRealtimeTest, LegacyLowLatencyBottomGateDispatchesNextGroupInCreatingWalTurn) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::LegacySession, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 3, true));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedLastTsForReader(RealtimePipelineHarness::kReaderTaskId, 1000));

  Stub          clockStub;
  const int64_t turnNow = 100 * NANOSECOND_PER_MSEC;
  clockStub.set(taosClockGetTime, captureRealtimePipelineTurnClock);
  resetRealtimePipelineTurnClock(turnNow, NANOSECOND_PER_MSEC, turnNow);
  const PipelineWalGroup group42 = {42, 1001, {1000, 2000}, {1, 2}, 2};
  const PipelineWalGroup group43 = {43, 1002, {1000, 2000}, {3, 4}, 2};

  ASSERT_TRUE(harness.feedGroups({group42, group43}));
  SSTriggerRealtimeGroup* pGroup42 = harness.group(42);
  SSTriggerRealtimeGroup* pGroup43 = harness.group(43);
  ASSERT_NE(nullptr, pGroup42);
  ASSERT_NE(nullptr, pGroup43);
  ASSERT_EQ(2, harness.calcSendCount()) << "pending42=" << pGroup42->pPendingCalcParams.neles
                                        << " pending43=" << pGroup43->pPendingCalcParams.neles
                                        << " next42=" << pGroup42->nextExecTime << " next43=" << pGroup43->nextExecTime
                                        << " heapSize=" << heapSize(harness.context()->pMaxDelayHeap)
                                        << " wallClockCalls=" << gRealtimePipelineTurnWallClockCalls;
  const SSTriggerCalcRequest* pFirst = harness.capturedCalc(0);
  const SSTriggerCalcRequest* pSecond = harness.capturedCalc(1);
  ASSERT_NE(nullptr, pFirst);
  ASSERT_NE(nullptr, pSecond);
  EXPECT_NE(pFirst->gid, pSecond->gid);
  EXPECT_TRUE((pFirst->gid == 42 && pSecond->gid == 43) || (pFirst->gid == 43 && pSecond->gid == 42));
  for (const SSTriggerCalcRequest* pRequest : {pFirst, pSecond}) {
    ASSERT_NE(nullptr, pRequest->params);
    ASSERT_EQ(1, taosArrayGetSize(pRequest->params));
    const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 0));
    ASSERT_NE(nullptr, pParam);
    EXPECT_GT(pParam->triggerTime, turnNow);
  }
}

