  EXPECT_EQ(NANOSECOND_PER_MSEC, pResume->idlestart);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pResume->idleend);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pResume->triggerTime);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pResume->notifyType);
  EXPECT_EQ(1000, pClose->wstart);
  EXPECT_EQ(1000, pClose->wend);
  EXPECT_EQ(0, pClose->wduration);
  EXPECT_EQ(1, pClose->wrownum);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pClose->notifyType);

  ASSERT_NE(nullptr, pRequest->pContextPolicy);
