static void expectOverlapDelayedParams(const SSTriggerCalcRequest* pRequest) {
  ASSERT_NE(nullptr, pRequest);
  ASSERT_NE(nullptr, pRequest->params);
  ASSERT_EQ(2, taosArrayGetSize(pRequest->params));
  int32_t firstLeafCount = 0;
  int32_t secondLeafCount = 0;
  for (int32_t i = 0; i < taosArrayGetSize(pRequest->params); ++i) {
    const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, i));
    ASSERT_NE(nullptr, pParam);
    EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pParam->notifyType);
    if (pParam->wstart == 0 && pParam->wend == 2999 && pParam->wrownum == 2) {
      ++firstLeafCount;
    } else if (pParam->wstart == 2000 && pParam->wend == 4999 && pParam->wrownum == 1) {
      ++secondLeafCount;
    } else {
      ADD_FAILURE() << "unexpected delayed leaf: [" << pParam->wstart << ',' << pParam->wend
                    << "], wrownum=" << pParam->wrownum;
    }
  }
  EXPECT_EQ(1, firstLeafCount);
  EXPECT_EQ(1, secondLeafCount);
}

TEST_F(StreamNestedRealtimeTest, CountAdapterConsumesOrderedInputWithoutOverridingDisorderAdmission) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::LegacyParityCount, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE));
  ASSERT_FALSE(harness.task()->ignoreDisorder);
  ASSERT_TRUE(harness.task()->countStepForcesOrderedInput);
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedVersionedRows({
      {RealtimePipelineHarness::kGid, RealtimePipelineHarness::kUid, {1000, 2000, 3000}, {1, 2, 3}, 2},
      {RealtimePipelineHarness::kGid, RealtimePipelineHarness::kUid, {2500, 4000, 5000}, {4, 5, 6}, 3},
  }));
  ASSERT_TRUE(harness.feedZeroRowWal());

  ASSERT_FALSE(harness.task()->ignoreDisorder);
  ASSERT_EQ(1, harness.calcSendCount());
  const SSTriggerCalcRequest* pCalc = harness.capturedCalc();
  ASSERT_NE(nullptr, pCalc);
  ASSERT_NE(nullptr, pCalc->params);
  ASSERT_EQ(2, taosArrayGetSize(pCalc->params));
  const auto* pFirst = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalc->params, 0));
  const auto* pSecond = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalc->params, 1));
  ASSERT_NE(nullptr, pFirst);
  ASSERT_NE(nullptr, pSecond);
  EXPECT_EQ(1000, pFirst->wstart);
  EXPECT_EQ(3000, pFirst->wend);
  EXPECT_EQ(3, pFirst->wrownum);
  EXPECT_EQ(3000, pSecond->wstart);
  EXPECT_EQ(5000, pSecond->wend);
  EXPECT_EQ(3, pSecond->wrownum);
}

