  SStreamCacheScope oldOuter = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 0, 0}});
  SStreamCacheScope newOuter = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 10000, 0}});
  EXPECT_EQ(std::vector<TSKEY>({8000, 9000}), harness.readScopeTimestamps(oldOuter));
