TEST_F(StreamNestedRealtimeTest, IgnoreNoDataOnlyFiltersLeafEvents) {
  std::array<PipelineAncestorObservation, 2> later = {};
  const auto                                 captureObservation = [](const SStreamNestedPendingCalcEvent* pEvent,
                                     PipelineAncestorObservation*         pObservation) {
    if (pEvent == nullptr || pObservation == nullptr || pEvent->leafIdentity.lineage.pScopes == nullptr ||
        taosArrayGetSize(pEvent->leafIdentity.lineage.pScopes) != 1 || pEvent->pSnapshots == nullptr ||
        taosArrayGetSize(pEvent->pSnapshots) != 1) {
      return false;
    }
    const auto* pScope = static_cast<const SScopeInstanceId*>(taosArrayGet(pEvent->leafIdentity.lineage.pScopes, 0));
    const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
    if (pScope == nullptr || pSnapshot == nullptr) return false;
    pObservation->scope = *pScope;
    pObservation->leafGid = pEvent->leafIdentity.gid;
    pObservation->leafTriggerType = pEvent->leafIdentity.triggerType;
    pObservation->leafOpeningTs = pEvent->leafIdentity.openingTs;
    pObservation->leafNativeDiscriminator = pEvent->leafIdentity.nativeDiscriminator;
    pObservation->snapshot = *pSnapshot;
    return true;
  };

  for (int32_t optionIndex = 0; optionIndex < 2; ++optionIndex) {
    const bool              ignoreNoData = optionIndex != 0;
    RealtimePipelineHarness harness;
    harness.enableNestedTrowsCacheProjection();
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::PureSlidingInterval, ignoreNoData, STRIGGER_EVENT_WINDOW_CLOSE,
                             STRIGGER_EVENT_WINDOW_CLOSE, 0, 1, false));
    ASSERT_NE(nullptr, harness.task()->pWindowPlan);
    ASSERT_NE(nullptr, harness.task()->pWindowPlan->pLayers);
    ASSERT_EQ(2, taosArrayGetSize(harness.task()->pWindowPlan->pLayers));
    auto* pRoot = static_cast<SStreamWindowLayerSpec*>(taosArrayGet(harness.task()->pWindowPlan->pLayers, 0));
    auto* pLeaf = static_cast<SStreamWindowLayerSpec*>(taosArrayGet(harness.task()->pWindowPlan->pLayers, 1));
    ASSERT_NE(nullptr, pRoot);
    ASSERT_NE(nullptr, pLeaf);
    pRoot->trigger.sliding.interval = 0;
    pRoot->trigger.sliding.sliding = 10000;
    pLeaf->trigger.sliding.interval = 0;
    pLeaf->trigger.sliding.sliding = 1000;

    ASSERT_TRUE(harness.start());
    ASSERT_TRUE(harness.feedRows({1000}, {7}));
    SSTriggerRealtimeGroup* pGroup = harness.group();
    ASSERT_NE(nullptr, pGroup);
    ASSERT_EQ(1, listNEles(&pGroup->pendingNestedEvents));
    const SListNode* pFirstNode = listHead(&pGroup->pendingNestedEvents);
    ASSERT_NE(nullptr, pFirstNode);
    const auto* pFirstEvent = reinterpret_cast<const SStreamNestedPendingCalcEvent*>(pFirstNode->data);
    EXPECT_EQ(STRIGGER_EVENT_WINDOW_CLOSE, pFirstEvent->calcParam.notifyType);
    EXPECT_EQ(1, pFirstEvent->calcParam.prevTs);
    EXPECT_EQ(1000, pFirstEvent->calcParam.currentTs);
    EXPECT_EQ(2000, pFirstEvent->calcParam.nextTs);
    ASSERT_TRUE(harness.feedEmptyFrontier(2000));
    ASSERT_TRUE(harness.feedRows({3000}, {8}));
    ASSERT_NE(nullptr, harness.context());
    SStreamCacheScope cacheScope = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 1, 0}});
    EXPECT_TRUE(harness.readScopeTimestamps(cacheScope).empty());
    EXPECT_EQ(0, listNEles(&pGroup->pendingNestedParWinEvents));
    const std::vector<std::pair<TSKEY, TSKEY>> expectedRanges =
        ignoreNoData ? std::vector<std::pair<TSKEY, TSKEY>>{{1, 1000}, {2001, 3000}}
                     : std::vector<std::pair<TSKEY, TSKEY>>{{1, 1000}, {1001, 2000}, {2001, 3000}};
    ASSERT_EQ(expectedRanges.size(), static_cast<size_t>(listNEles(&pGroup->pendingNestedEvents)));

    SListIter iter = {};
    tdListInitIter(&pGroup->pendingNestedEvents, &iter, TD_LIST_FORWARD);
    for (size_t eventIndex = 0; eventIndex < expectedRanges.size(); ++eventIndex) {
      SListNode* pNode = tdListNext(&iter);
      ASSERT_NE(nullptr, pNode);
      const auto* pEvent = reinterpret_cast<const SStreamNestedPendingCalcEvent*>(pNode->data);
      EXPECT_EQ(STREAM_CONTEXT_POLICY_ANCESTOR, pEvent->contextPolicy);
      EXPECT_EQ(STRIGGER_EVENT_WINDOW_CLOSE, pEvent->calcParam.notifyType);
      EXPECT_EQ(expectedRanges[eventIndex].first, pEvent->calcParam.prevTs);
      EXPECT_EQ(expectedRanges[eventIndex].second, pEvent->calcParam.currentTs);
      EXPECT_EQ(expectedRanges[eventIndex].second + 1000, pEvent->calcParam.nextTs);
      EXPECT_EQ(expectedRanges[eventIndex].first, pEvent->calcDataRange.skey);
      EXPECT_EQ(expectedRanges[eventIndex].second, pEvent->calcDataRange.ekey);
      EXPECT_EQ(RealtimePipelineHarness::kGid, pEvent->leafIdentity.gid);
      EXPECT_EQ(WINDOW_TYPE_INTERVAL, pEvent->leafIdentity.triggerType);
      EXPECT_EQ(expectedRanges[eventIndex].first, pEvent->leafIdentity.openingTs);
      EXPECT_EQ(0, pEvent->leafIdentity.nativeDiscriminator);
      PipelineAncestorObservation observation = {};
      ASSERT_TRUE(captureObservation(pEvent, &observation));
      EXPECT_EQ(0, observation.scope.layerIndex);
      EXPECT_EQ(WINDOW_TYPE_INTERVAL, observation.scope.triggerType);
      EXPECT_EQ(1, observation.scope.openingTs);
      EXPECT_EQ(0, observation.scope.nativeDiscriminator);
      EXPECT_EQ(0, observation.snapshot.layerIndex);
      EXPECT_EQ(WINDOW_TYPE_INTERVAL, observation.snapshot.triggerType);
      EXPECT_EQ(1, observation.snapshot.values.sliding.prevTs);
      EXPECT_EQ(10000, observation.snapshot.values.sliding.currentTs);
      EXPECT_EQ(20000, observation.snapshot.values.sliding.nextTs);
      if (expectedRanges[eventIndex].first == 2001) later[optionIndex] = observation;
    }
    EXPECT_EQ(nullptr, tdListNext(&iter));
    RealtimePipelineHarness::destroyScope(&cacheScope);
  }
  EXPECT_EQ(later[0].scope.layerIndex, later[1].scope.layerIndex);
  EXPECT_EQ(later[0].scope.triggerType, later[1].scope.triggerType);
  EXPECT_EQ(later[0].scope.openingTs, later[1].scope.openingTs);
  EXPECT_EQ(later[0].scope.nativeDiscriminator, later[1].scope.nativeDiscriminator);
  EXPECT_EQ(later[0].leafGid, later[1].leafGid);
  EXPECT_EQ(later[0].leafTriggerType, later[1].leafTriggerType);
  EXPECT_EQ(later[0].leafOpeningTs, later[1].leafOpeningTs);
  EXPECT_EQ(later[0].leafNativeDiscriminator, later[1].leafNativeDiscriminator);
  EXPECT_EQ(later[0].snapshot.layerIndex, later[1].snapshot.layerIndex);
  EXPECT_EQ(later[0].snapshot.triggerType, later[1].snapshot.triggerType);
  EXPECT_EQ(later[0].snapshot.placeholderMask, later[1].snapshot.placeholderMask);
  EXPECT_EQ(later[0].snapshot.values.sliding.prevTs, later[1].snapshot.values.sliding.prevTs);
  EXPECT_EQ(later[0].snapshot.values.sliding.currentTs, later[1].snapshot.values.sliding.currentTs);
  EXPECT_EQ(later[0].snapshot.values.sliding.nextTs, later[1].snapshot.values.sliding.nextTs);
  EXPECT_EQ(0, later[0].scope.layerIndex);
  EXPECT_EQ(WINDOW_TYPE_INTERVAL, later[0].scope.triggerType);
  EXPECT_EQ(1, later[0].scope.openingTs);
  EXPECT_EQ(1, later[0].snapshot.values.sliding.prevTs);
  EXPECT_EQ(10000, later[0].snapshot.values.sliding.currentTs);
  EXPECT_EQ(20000, later[0].snapshot.values.sliding.nextTs);
  EXPECT_EQ(RealtimePipelineHarness::kGid, later[0].leafGid);
  EXPECT_EQ(WINDOW_TYPE_INTERVAL, later[0].leafTriggerType);
  EXPECT_EQ(2001, later[0].leafOpeningTs);
  EXPECT_EQ(0, later[0].leafNativeDiscriminator);
}

TEST_F(StreamNestedRealtimeTest, PureSlidingRootWithoutFilterPullsRowsAtCalcTime) {
  for (RealtimePipelinePlan plan :
       {RealtimePipelinePlan::PureSlidingSession, RealtimePipelinePlan::PureSlidingInterval}) {
    RealtimePipelineHarness harness;
    harness.enableNestedTrowsCacheProjection();
    ASSERT_TRUE(harness.init(plan));
    ASSERT_TRUE(harness.start());
    ASSERT_TRUE(harness.feedRows({1000, 2000}, {1, 2}));
    ASSERT_NE(nullptr, harness.context());
    EXPECT_NE(STRIGGER_WAL_META_ONLY, harness.context()->walMode);
    ASSERT_NE(nullptr, harness.context()->pCalcDataCache);
    EXPECT_EQ(0, harness.calcSendCount());
    ASSERT_EQ(1, harness.pendingPullCount(STRIGGER_PULL_WAL_CALC_DATA_NEW));
    SStreamCacheScope firstScope = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 1, 0}});
    SStreamCacheScope secondScope = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 1001, 0}});
    EXPECT_TRUE(harness.readScopeTimestamps(firstScope).empty());
    EXPECT_TRUE(harness.readScopeTimestamps(secondScope).empty());
    ASSERT_TRUE(harness.respondCalcRows({1000, 2000}, {1, 2}));
    EXPECT_EQ(1, harness.calcSendCount());
    EXPECT_EQ(std::vector<TSKEY>({1000}), harness.readScopeTimestamps(firstScope));
    EXPECT_EQ(std::vector<TSKEY>({2000}), harness.readScopeTimestamps(secondScope));
    RealtimePipelineHarness::destroyScope(&firstScope);
    RealtimePipelineHarness::destroyScope(&secondScope);
  }
}

