SStreamAncestorContext* makePoolAncestorContext(int64_t gid) {
  auto* context = static_cast<SStreamAncestorContext*>(taosMemoryCalloc(1, sizeof(SStreamAncestorContext)));
  EXPECT_NE(context, nullptr);
  if (context == nullptr) return nullptr;
  context->pParamContexts = taosArrayInit(1, sizeof(SStreamAncestorParamContext));
  EXPECT_NE(context->pParamContexts, nullptr);
  if (context->pParamContexts == nullptr) return context;

  SStreamAncestorParamContext param = {};
  param.leafIdentity.gid = gid;
  param.leafIdentity.triggerType = WINDOW_TYPE_COUNT;
  param.leafIdentity.lineage.pScopes = taosArrayInit(1, sizeof(SScopeInstanceId));
  EXPECT_NE(param.leafIdentity.lineage.pScopes, nullptr);
  const SScopeInstanceId scope = {
      .layerIndex = 0, .triggerType = WINDOW_TYPE_INTERVAL, .openingTs = 100, .nativeDiscriminator = 1};
  EXPECT_NE(taosArrayPush(param.leafIdentity.lineage.pScopes, &scope), nullptr);
  param.pSnapshots = taosArrayInit(1, sizeof(SWindowAncestorSnapshot));
  EXPECT_NE(param.pSnapshots, nullptr);
  const SWindowAncestorSnapshot snapshot = {
      .layerIndex = 0, .triggerType = WINDOW_TYPE_INTERVAL, .values = {.sliding = {.currentTs = 100}}};
  EXPECT_NE(taosArrayPush(param.pSnapshots, &snapshot), nullptr);
  EXPECT_NE(taosArrayPush(context->pParamContexts, &param), nullptr);
  return context;
}

SStreamContextPolicy* makePoolContextPolicy(int64_t gid) {
  auto* policy = static_cast<SStreamContextPolicy*>(taosMemoryCalloc(1, sizeof(SStreamContextPolicy)));
  EXPECT_NE(policy, nullptr);
  if (policy == nullptr) return nullptr;
  policy->pEntries = taosArrayInit(1, sizeof(SStreamContextPolicyEntry));
  EXPECT_NE(policy->pEntries, nullptr);
  if (policy->pEntries == nullptr) return policy;
  const SStreamContextPolicyEntry entry = {
      .gid = gid, .paramIndex = 0, .contextPolicy = STREAM_CONTEXT_POLICY_ANCESTOR};
  EXPECT_NE(taosArrayPush(policy->pEntries, &entry), nullptr);
  return policy;
}

bool setPoolContextDiscriminator(SStreamAncestorContext* context, int64_t discriminator) {
  auto* param = static_cast<SStreamAncestorParamContext*>(
      taosArrayGet(context == nullptr ? nullptr : context->pParamContexts, 0));
  if (param == nullptr) return false;
  auto* scope = static_cast<SScopeInstanceId*>(taosArrayGet(param->leafIdentity.lineage.pScopes, 0));
  if (scope == nullptr) return false;
  scope->nativeDiscriminator = discriminator;
  return true;
}

bool appendPoolParamIdentity(SStreamAncestorContext* context, int64_t gid, int64_t discriminator, int32_t paramIndex) {
  if (context == nullptr || context->pParamContexts == nullptr) return false;
  SStreamAncestorParamContext param = {};
  param.paramIndex = paramIndex;
  param.leafIdentity.gid = gid;
  param.leafIdentity.triggerType = WINDOW_TYPE_COUNT;
  param.leafIdentity.lineage.pScopes = taosArrayInit(1, sizeof(SScopeInstanceId));
  if (param.leafIdentity.lineage.pScopes == nullptr) return false;
  const SScopeInstanceId scope = {
      .layerIndex = 0,
      .triggerType = WINDOW_TYPE_INTERVAL,
      .openingTs = 100,
      .nativeDiscriminator = discriminator,
  };
  if (taosArrayPush(param.leafIdentity.lineage.pScopes, &scope) == nullptr ||
      taosArrayPush(context->pParamContexts, &param) == nullptr) {
    taosArrayDestroy(param.leafIdentity.lineage.pScopes);
    return false;
  }
  return true;
}

bool appendPoolReadScopeBinding(SStreamAncestorContext* context, int64_t gid, int64_t discriminator,
                                int32_t readInfoIndex) {
  auto* param = static_cast<SStreamAncestorParamContext*>(
      taosArrayGet(context == nullptr ? nullptr : context->pParamContexts, 0));
  if (param == nullptr) return false;
  if (context->pReadScopeBindings == nullptr) {
    context->pReadScopeBindings = taosArrayInit(2, sizeof(SStreamReadScopeBinding));
    if (context->pReadScopeBindings == nullptr) return false;
  }

  SStreamReadScopeBinding binding = {.vgId = 7, .readInfoIndex = readInfoIndex, .scope = {.gid = gid}};
  binding.scope.lineage.pScopes = taosArrayDup(param->leafIdentity.lineage.pScopes, nullptr);
  if (binding.scope.lineage.pScopes == nullptr) return false;
  auto* scope = static_cast<SScopeInstanceId*>(taosArrayGet(binding.scope.lineage.pScopes, 0));
  if (scope == nullptr) {
    taosArrayDestroy(binding.scope.lineage.pScopes);
    return false;
  }
  scope->nativeDiscriminator = discriminator;
  if (taosArrayPush(context->pReadScopeBindings, &binding) == nullptr) {
    taosArrayDestroy(binding.scope.lineage.pScopes);
    return false;
  }
  return true;
}

SStreamAncestorContext* makePoolProjectedContext(int64_t gid, int64_t discriminator) {
  SStreamAncestorContext* context = makePoolAncestorContext(gid);
  EXPECT_TRUE(setPoolContextDiscriminator(context, discriminator));
  EXPECT_TRUE(appendPoolReadScopeBinding(context, gid, discriminator, 0));
  return context;
}

SSDataBlock* makePoolCacheBlock() {
  SSDataBlock* block = nullptr;
  if (createDataBlock(&block) != TSDB_CODE_SUCCESS) return nullptr;
  SColumnInfoData tsInfo = createColumnInfoData(TSDB_DATA_TYPE_TIMESTAMP, sizeof(TSKEY), 1);
  SColumnInfoData valueInfo = createColumnInfoData(TSDB_DATA_TYPE_INT, sizeof(int32_t), 2);
  if (blockDataAppendColInfo(block, &tsInfo) != TSDB_CODE_SUCCESS ||
      blockDataAppendColInfo(block, &valueInfo) != TSDB_CODE_SUCCESS ||
      blockDataEnsureCapacity(block, 2) != TSDB_CODE_SUCCESS) {
    blockDataDestroy(block);
    return nullptr;
  }
  auto*         tsCol = static_cast<SColumnInfoData*>(taosArrayGet(block->pDataBlock, 0));
  auto*         valueCol = static_cast<SColumnInfoData*>(taosArrayGet(block->pDataBlock, 1));
  const TSKEY   timestamps[] = {100, 101};
  const int32_t values[] = {10, 20};
  for (int32_t row = 0; row < 2; ++row) {
    if (colDataSetVal(tsCol, row, reinterpret_cast<const char*>(&timestamps[row]), false) != TSDB_CODE_SUCCESS ||
        colDataSetVal(valueCol, row, reinterpret_cast<const char*>(&values[row]), false) != TSDB_CODE_SUCCESS) {
      blockDataDestroy(block);
      return nullptr;
    }
  }
  block->info.rows = 2;
  return block;
}

class CalcPoolHarness {
 public:
  bool init() {
    task_.task.streamId = 0x700;
    task_.task.taskId = 0x701;
    task_.triggerType = STREAM_TRIGGER_COUNT;
    task_.lowLatencyCalc = true;
    taosInitRWLatch(&task_.calcPoolLock);

    task_.runnerList = taosArrayInit_s(sizeof(SStreamRunnerTarget), 1);
    if (task_.runnerList == nullptr) return false;
    auto* runner = static_cast<SStreamRunnerTarget*>(taosArrayGet(task_.runnerList, 0));
    runner->addr.taskId = 0x702;
    runner->execReplica = 2;

    task_.pCalcNodes = taosArrayInit_s(sizeof(SSTriggerCalcNode), 1);
    if (task_.pCalcNodes == nullptr) return false;
    auto* node = static_cast<SSTriggerCalcNode*>(taosArrayGet(task_.pCalcNodes, 0));
    node->pSlots = taosArrayInit_s(sizeof(SSTriggerCalcSlot), 2);
    if (node->pSlots == nullptr) return false;
    for (int32_t i = 0; i < 2; ++i) {
      auto* slot = static_cast<SSTriggerCalcSlot*>(taosArrayGet(node->pSlots, i));
      TD_DLIST_APPEND(&node->idleSlots, slot);
    }

    task_.pGroupRunning = tSimpleHashInit(4, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BINARY));
    task_.pSessionRunning = tSimpleHashInit(4, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BIGINT));
    if (task_.pGroupRunning == nullptr || task_.pSessionRunning == nullptr) return false;

    realtime_.pTask = &task_;
    realtime_.sessionId = kRealtimeSessionId;
    realtime_.status = STRIGGER_CONTEXT_IDLE;
    tdListInit(&realtime_.retryCalcReqs, POINTER_BYTES);
    task_.pRealtimeContext = &realtime_;
    return true;
  }

  bool enableCacheRead() {
    if (gStreamMgmt.taskMap != nullptr || initStreamDataSink() != TSDB_CODE_SUCCESS) return false;
    dataSinkOwned_ = true;
    if (stCreateCalcDataCacheIterMap(&realtime_.pCalcDataCacheIters) != TSDB_CODE_SUCCESS) return false;

    task_.task.type = STREAM_TRIGGER_TASK;
    task_.task.nodeId = 7;
    task_.addOptions = STREAM_OPTION_NESTED_WINDOW_PLAN;
    taosInitRWLatch(&task_.task.entryLock);
    gStreamMgmt.taskMap = taosHashInit(1, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BINARY), false, HASH_ENTRY_LOCK);
    if (gStreamMgmt.taskMap == nullptr) return false;
    taskMapOwned_ = true;
    SStreamTask* task = reinterpret_cast<SStreamTask*>(&task_);
    if (taosHashPut(gStreamMgmt.taskMap, &task_.task.streamId, sizeof(task_.task.streamId) + sizeof(task_.task.taskId),
                    &task, POINTER_BYTES) != TSDB_CODE_SUCCESS) {
      return false;
    }
    taskRegistered_ = true;
    return initStreamDataCache(task_.task.streamId, task_.task.taskId, realtime_.sessionId, DATA_CLEAN_IMMEDIATE, 0,
                               &cache_) == TSDB_CODE_SUCCESS;
  }

  ~CalcPoolHarness() {
    if (taskRegistered_) {
      EXPECT_EQ(taosHashRemove(gStreamMgmt.taskMap, &task_.task.streamId,
                               sizeof(task_.task.streamId) + sizeof(task_.task.taskId)),
                TSDB_CODE_SUCCESS);
    }
    if (taskMapOwned_) {
      taosHashCleanup(gStreamMgmt.taskMap);
      gStreamMgmt.taskMap = nullptr;
    }
    taosHashCleanup(realtime_.pCalcDataCacheIters);
    realtime_.pCalcDataCacheIters = nullptr;
    if (dataSinkOwned_) destroyDataSinkMgr();
    if (task_.pCalcNodes != nullptr) {
      auto* node = static_cast<SSTriggerCalcNode*>(taosArrayGet(task_.pCalcNodes, 0));
      if (node != nullptr && node->pSlots != nullptr) {
        for (int32_t i = 0; i < taosArrayGetSize(node->pSlots); ++i) {
          auto* slot = static_cast<SSTriggerCalcSlot*>(taosArrayGet(node->pSlots, i));
          tDestroySTriggerCalcRequest(&slot->req);
        }
        taosArrayDestroy(node->pSlots);
      }
      taosArrayDestroy(task_.pCalcNodes);
    }
    tSimpleHashCleanup(task_.pGroupRunning);
    tSimpleHashCleanup(task_.pSessionRunning);
    taosArrayDestroy(task_.runnerList);
    tdListEmpty(&realtime_.retryCalcReqs);
  }

  void attachContext(SSTriggerCalcRequest* request) {
    SSTriggerCalcParam param = {.wstart = 100, .wend = 199, .notifyType = STRIGGER_EVENT_WINDOW_CLOSE};
    ASSERT_NE(taosArrayPush(request->params, &param), nullptr);
    request->pContextPolicy = makePoolContextPolicy(request->gid);
    ASSERT_NE(request->pContextPolicy, nullptr);
    request->pAncestorContext = makePoolAncestorContext(request->gid);
    ASSERT_NE(request->pAncestorContext, nullptr);
  }

  int32_t readCacheIterator(int64_t gid, int64_t sessionId, SStreamContextPolicy* policy,
                            SStreamAncestorContext* context, int32_t* value, bool* finished, bool multiGroup = false) {
    if (value == nullptr || finished == nullptr) return TSDB_CODE_INVALID_PARA;
    SStreamRuntimeFuncInfo runtime = {};
    runtime.groupId = gid;
    runtime.curIdx = 0;
    runtime.sessionId = sessionId;
    runtime.curNodeId = task_.task.nodeId;
    runtime.isMultiGroupCalc = multiGroup;
    runtime.pContextPolicy = policy;
    runtime.pAncestorContext = context;
    SStreamCacheReadInfo readInfo = {};
    readInfo.taskInfo.streamId = task_.task.streamId;
    readInfo.taskInfo.taskId = task_.task.taskId;
    readInfo.taskInfo.sessionId = sessionId;
    readInfo.gid = gid;
    readInfo.start = 100;
    readInfo.end = 101;
    readInfo.pRuntime = &runtime;
    int32_t code = stRunnerFetchDataFromCache(&readInfo, finished);
    if (code == TSDB_CODE_SUCCESS && readInfo.pBlock != nullptr) {
      const auto* values = static_cast<const SColumnInfoData*>(taosArrayGet(readInfo.pBlock->pDataBlock, 1));
      if (values == nullptr) {
        code = TSDB_CODE_INVALID_PARA;
      } else {
        *value = *reinterpret_cast<const int32_t*>(colDataGetData(values, 0));
      }
    }
    blockDataDestroy(readInfo.pBlock);
    stClearStreamCacheReadScope(&readInfo);
    return code;
  }

  int32_t populateCacheIterator(int64_t gid, int64_t sessionId, SStreamContextPolicy* policy,
                                SStreamAncestorContext* context, bool multiGroup = false) {
    const auto* param = static_cast<const SStreamAncestorParamContext*>(taosArrayGet(context->pParamContexts, 0));
    if (param == nullptr) return TSDB_CODE_INVALID_PARA;
    SStreamCacheScope scope = {.gid = param->leafIdentity.gid, .lineage = param->leafIdentity.lineage};
    SSDataBlock*      source = makePoolCacheBlock();
    if (source == nullptr) return terrno;
    source->info.id.blockId = 1;
    int32_t code = putStreamDataCacheScoped(cache_, &scope, 100, 100, source, 0, 0);
    if (code == TSDB_CODE_SUCCESS) {
      source->info.id.blockId = 2;
      code = putStreamDataCacheScoped(cache_, &scope, 101, 101, source, 1, 1);
    }
    blockDataDestroy(source);
    if (code != TSDB_CODE_SUCCESS) return code;
    int32_t value = 0;
    bool    finished = false;
    code = readCacheIterator(gid, sessionId, policy, context, &value, &finished, multiGroup);
    if (code != TSDB_CODE_SUCCESS) return code;
    return !finished && value == 10 ? TSDB_CODE_SUCCESS : TSDB_CODE_INTERNAL_ERROR;
  }

  int32_t cacheIteratorCount() const { return taosHashGetSize(realtime_.pCalcDataCacheIters); }

  int32_t processResponse(SSTriggerCalcRequest* request, int32_t responseCode) {
    SSTriggerAHandle responseAhandle = {};
    responseAhandle.param = request;
    SMsgSendInfo responseSendInfo = {};
    responseSendInfo.param = &responseAhandle;
    SRpcMsg response = {};
    response.msgType = TDMT_STREAM_TRIGGER_CALC_RSP;
    response.code = responseCode;
    response.info.ahandle = &responseSendInfo;
    int64_t errorTaskId = 0;
    return stTriggerTaskProcessRsp(&task_.task, &response, &errorTaskId);
  }

  SStreamTriggerTask task_ = {};

 private:
  SSTriggerRealtimeContext realtime_ = {};
  void*                    cache_ = nullptr;
  bool                     dataSinkOwned_ = false;
  bool                     taskMapOwned_ = false;
  bool                     taskRegistered_ = false;
};

void expectTerminalResponseClearsPool(int32_t responseCode, int64_t placeholderMask = 0) {
  CalcPoolHarness harness;
  ASSERT_TRUE(harness.init());
  ASSERT_TRUE(harness.enableCacheRead());
  harness.task_.placeHolderBitmap = placeholderMask;
  SSTriggerCalcRequest* request = nullptr;
  ASSERT_EQ(stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &request), TSDB_CODE_SUCCESS);
  ASSERT_NE(request, nullptr);
  harness.attachContext(request);
  auto* targetPolicyB = makePoolContextPolicy(request->gid);
  auto* targetContextB = makePoolAncestorContext(request->gid);
  auto* sidePolicy = makePoolContextPolicy(request->gid);
  auto* sideContext = makePoolAncestorContext(request->gid);
  ASSERT_NE(nullptr, targetPolicyB);
  ASSERT_NE(nullptr, targetContextB);
  ASSERT_NE(nullptr, sidePolicy);
  ASSERT_NE(nullptr, sideContext);
  ASSERT_TRUE(setPoolContextDiscriminator(targetContextB, 3));
  auto* sideParam = static_cast<SStreamAncestorParamContext*>(taosArrayGet(sideContext->pParamContexts, 0));
  ASSERT_NE(nullptr, sideParam);
  auto* sideScope = static_cast<SScopeInstanceId*>(taosArrayGet(sideParam->leafIdentity.lineage.pScopes, 0));
  ASSERT_NE(nullptr, sideScope);
  sideScope->nativeDiscriminator = 2;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.populateCacheIterator(request->gid, request->sessionId, request->pContextPolicy,
                                                             request->pAncestorContext));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, targetPolicyB, targetContextB));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, sidePolicy, sideContext));
  ASSERT_EQ(3, harness.cacheIteratorCount());
  ASSERT_TRUE(appendPoolParamIdentity(request->pAncestorContext, request->gid, 3, 1));
  ASSERT_TRUE(appendPoolParamIdentity(request->pAncestorContext, request->gid, 1, 2));
  SSTriggerCalcRequest* const original = request;

  SSTriggerCalcRequest* blocker = nullptr;
  ASSERT_EQ(stTriggerTaskAcquireRequest(&harness.task_, kHistorySessionId, 202, &blocker), TSDB_CODE_SUCCESS);
  ASSERT_NE(blocker, nullptr);

  const int32_t code = harness.processResponse(request, responseCode);
  if (responseCode == TSDB_CODE_SUCCESS) {
    EXPECT_EQ(code, TSDB_CODE_SUCCESS);
  } else {
    EXPECT_EQ(code, responseCode);
  }
  EXPECT_EQ(1, harness.cacheIteratorCount());
  int32_t sideValue = 0;
  bool    sideFinished = false;
  EXPECT_EQ(TSDB_CODE_SUCCESS,
            harness.readCacheIterator(101, kRealtimeSessionId, sidePolicy, sideContext, &sideValue, &sideFinished));
  EXPECT_EQ(20, sideValue);
  EXPECT_TRUE(sideFinished);
  EXPECT_EQ(0, harness.cacheIteratorCount());
  tDestroyStreamContextPolicy(&targetPolicyB);
  tDestroyStreamAncestorContext(&targetContextB);
  tDestroyStreamContextPolicy(&sidePolicy);
  tDestroyStreamAncestorContext(&sideContext);

  SSTriggerCalcRequest* reused = nullptr;
  ASSERT_EQ(stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &reused), TSDB_CODE_SUCCESS);
  ASSERT_EQ(reused, original);
  EXPECT_EQ(reused->pContextPolicy, nullptr);
  EXPECT_EQ(reused->pAncestorContext, nullptr);
  EXPECT_EQ(stTriggerTaskReleaseRequest(&harness.task_, &reused, false), TSDB_CODE_SUCCESS);
  EXPECT_EQ(stTriggerTaskReleaseRequest(&harness.task_, &blocker, false), TSDB_CODE_SUCCESS);
}

TEST_F(StreamTriggerTaskTest, ContextPairPoolClearsAfterSuccess) {
  expectTerminalResponseClearsPool(TSDB_CODE_SUCCESS);
}

TEST_F(StreamTriggerTaskTest, ContextPairPoolClearsAfterCancel) {
  expectTerminalResponseClearsPool(TSDB_CODE_STREAM_EXEC_CANCELLED);
}

TEST_F(StreamTriggerTaskTest, ContextPairPoolClearsAfterTerminalFailure) {
  expectTerminalResponseClearsPool(TSDB_CODE_INVALID_PARA);
  expectTerminalResponseClearsPool(TSDB_CODE_TDB_INVALID_TABLE_SCHEMA_VER, PLACE_HOLDER_PARTITION_ROWS);
}

TEST_F(StreamTriggerTaskTest, MultiGroupTerminalResponseClearsEveryBoundScopeOnly) {
  CalcPoolHarness harness;
  ASSERT_TRUE(harness.init());
  ASSERT_TRUE(harness.enableCacheRead());
  harness.task_.multiGroupBatch = true;

  SSTriggerCalcRequest* request = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &request));
  ASSERT_NE(nullptr, request);
  harness.attachContext(request);
  ASSERT_TRUE(setPoolContextDiscriminator(request->pAncestorContext, 4));
  ASSERT_TRUE(appendPoolReadScopeBinding(request->pAncestorContext, request->gid, 1, 0));
  ASSERT_TRUE(appendPoolReadScopeBinding(request->pAncestorContext, request->gid, 2, 1));

  auto* targetPolicyA = makePoolContextPolicy(request->gid);
  auto* targetPolicyB = makePoolContextPolicy(request->gid);
  auto* sidePolicy = makePoolContextPolicy(request->gid);
  auto* decoyPolicy = makePoolContextPolicy(request->gid);
  auto* targetContextA = makePoolProjectedContext(request->gid, 1);
  auto* targetContextB = makePoolProjectedContext(request->gid, 2);
  auto* sideContext = makePoolProjectedContext(request->gid, 3);
  auto* decoyContext = makePoolAncestorContext(request->gid);
  ASSERT_TRUE(setPoolContextDiscriminator(decoyContext, 4));
  ASSERT_NE(nullptr, targetPolicyA);
  ASSERT_NE(nullptr, targetPolicyB);
  ASSERT_NE(nullptr, sidePolicy);
  ASSERT_NE(nullptr, decoyPolicy);
  ASSERT_NE(nullptr, targetContextA);
  ASSERT_NE(nullptr, targetContextB);
  ASSERT_NE(nullptr, sideContext);
  ASSERT_NE(nullptr, decoyContext);

  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, targetPolicyA, targetContextA, true));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, targetPolicyB, targetContextB, true));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, sidePolicy, sideContext, true));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, decoyPolicy, decoyContext));
  ASSERT_EQ(4, harness.cacheIteratorCount());

  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.processResponse(request, TSDB_CODE_SUCCESS));
  EXPECT_EQ(2, harness.cacheIteratorCount());

  int32_t sideValue = 0;
  int32_t decoyValue = 0;
  bool    sideFinished = false;
  bool    decoyFinished = false;
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.readCacheIterator(101, kRealtimeSessionId, sidePolicy, sideContext, &sideValue,
                                                         &sideFinished, true));
  EXPECT_EQ(TSDB_CODE_SUCCESS,
            harness.readCacheIterator(101, kRealtimeSessionId, decoyPolicy, decoyContext, &decoyValue, &decoyFinished));
  EXPECT_EQ(20, sideValue);
  EXPECT_EQ(20, decoyValue);
  EXPECT_TRUE(sideFinished);
  EXPECT_TRUE(decoyFinished);
  EXPECT_EQ(0, harness.cacheIteratorCount());

  tDestroyStreamContextPolicy(&targetPolicyA);
  tDestroyStreamContextPolicy(&targetPolicyB);
  tDestroyStreamContextPolicy(&sidePolicy);
  tDestroyStreamContextPolicy(&decoyPolicy);
  tDestroyStreamAncestorContext(&targetContextA);
  tDestroyStreamAncestorContext(&targetContextB);
  tDestroyStreamAncestorContext(&sideContext);
  tDestroyStreamAncestorContext(&decoyContext);
}

TEST_F(StreamTriggerTaskTest, ContextPairAcquireRejectsResidualOwnedObject) {
  CalcPoolHarness harness;
  ASSERT_TRUE(harness.init());
  auto* node = static_cast<SSTriggerCalcNode*>(taosArrayGet(harness.task_.pCalcNodes, 0));
  ASSERT_NE(node, nullptr);
  auto* slot = TD_DLIST_HEAD(&node->idleSlots);
  ASSERT_NE(slot, nullptr);
  slot->req.pContextPolicy = makePoolContextPolicy(101);
  slot->req.pAncestorContext = makePoolAncestorContext(101);

  SSTriggerCalcRequest* request = reinterpret_cast<SSTriggerCalcRequest*>(UINTPTR_MAX);
  EXPECT_EQ(stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &request), TSDB_CODE_INTERNAL_ERROR);
  EXPECT_EQ(request, nullptr);
}

struct RetryCalcCapture {
  SSTriggerCalcRequest* request = nullptr;
};

RetryCalcCapture gRetryCalcCapture;

int32_t captureRetryCalcRequest(const SEpSet*, SRpcMsg* message) {
  auto* sendInfo = static_cast<SMsgSendInfo*>(message->info.ahandle);
  auto* ahandle = static_cast<SSTriggerAHandle*>(sendInfo->param);
  gRetryCalcCapture.request = static_cast<SSTriggerCalcRequest*>(ahandle->param);
  rpcFreeCont(message->pCont);
  message->pCont = nullptr;
  destroyAhandle(message->info.ahandle);
  message->info.ahandle = nullptr;
  return TSDB_CODE_SUCCESS;
}

TEST_F(StreamTriggerTaskTest, ContextPairRetryKeepsSameOwnedObjects) {
  CalcPoolHarness harness;
  ASSERT_TRUE(harness.init());
  ASSERT_TRUE(harness.enableCacheRead());
  SSTriggerCalcRequest* request = nullptr;
  ASSERT_EQ(stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &request), TSDB_CODE_SUCCESS);
  ASSERT_NE(request, nullptr);
  harness.attachContext(request);
  auto* sidePolicy = makePoolContextPolicy(request->gid);
  auto* sideContext = makePoolAncestorContext(request->gid);
  ASSERT_NE(nullptr, sidePolicy);
  ASSERT_NE(nullptr, sideContext);
  auto* sideParam = static_cast<SStreamAncestorParamContext*>(taosArrayGet(sideContext->pParamContexts, 0));
  ASSERT_NE(nullptr, sideParam);
  auto* sideScope = static_cast<SScopeInstanceId*>(taosArrayGet(sideParam->leafIdentity.lineage.pScopes, 0));
  ASSERT_NE(nullptr, sideScope);
  sideScope->nativeDiscriminator = 2;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.populateCacheIterator(request->gid, request->sessionId, request->pContextPolicy,
                                                             request->pAncestorContext));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.populateCacheIterator(request->gid, request->sessionId, sidePolicy, sideContext));
  ASSERT_EQ(2, harness.cacheIteratorCount());
  SStreamContextPolicy* const   policy = request->pContextPolicy;
  SStreamAncestorContext* const context = request->pAncestorContext;
  gRetryCalcCapture = {};
  Stub stub;
  stub.set(tmsgSendReq, captureRetryCalcRequest);

  EXPECT_EQ(harness.processResponse(request, TSDB_CODE_TDB_INVALID_TABLE_SCHEMA_VER), TSDB_CODE_SUCCESS);
  EXPECT_EQ(gRetryCalcCapture.request, request);
  EXPECT_EQ(request->pContextPolicy, policy);
  EXPECT_EQ(request->pAncestorContext, context);
  EXPECT_EQ(2, harness.cacheIteratorCount());

  int32_t targetValue = 0;
  int32_t sideValue = 0;
  bool    targetFinished = false;
  bool    sideFinished = false;
  EXPECT_EQ(TSDB_CODE_SUCCESS,
            harness.readCacheIterator(101, kRealtimeSessionId, policy, context, &targetValue, &targetFinished));
  EXPECT_EQ(TSDB_CODE_SUCCESS,
            harness.readCacheIterator(101, kRealtimeSessionId, sidePolicy, sideContext, &sideValue, &sideFinished));
  EXPECT_EQ(20, targetValue);
  EXPECT_EQ(20, sideValue);
  EXPECT_TRUE(targetFinished);
  EXPECT_TRUE(sideFinished);
  EXPECT_EQ(0, harness.cacheIteratorCount());

  SSTriggerCalcRequest* unavailable = nullptr;
  EXPECT_EQ(stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &unavailable), TSDB_CODE_SUCCESS);
  EXPECT_EQ(unavailable, nullptr);
  EXPECT_EQ(stTriggerTaskReleaseRequest(&harness.task_, &request, false), TSDB_CODE_SUCCESS);
  tDestroyStreamContextPolicy(&sidePolicy);
  tDestroyStreamAncestorContext(&sideContext);
}

class StreamNestedRecalcTest : public ::testing::Test {};

static int32_t startTask14RealtimeIdentity(NestedHistoryHarness* harness, bool configureNotifyTarget) {
  if (!harness->deploy(NestedHistoryPlan::SessionUnitCount, 0, NestedHistoryHarness::kScanStart - 1,
                       configureNotifyTarget, 0, false, false, 2, true, true, false)) {
    return TSDB_CODE_INTERNAL_ERROR;
  }
  if (configureNotifyTarget &&
      !harness->setHistoryEffectPolicy(STRIGGER_EVENT_WINDOW_CLOSE, STRIGGER_EVENT_WINDOW_CLOSE, false)) {
    return TSDB_CODE_OUT_OF_MEMORY;
  }
  int32_t code = harness->startAndCreateHistory();
  if (code != TSDB_CODE_SUCCESS) return code;
  code = harness->respondRealtimeWal(NestedHistoryHarness::kScanStart, 10);
  if (code != TSDB_CODE_SUCCESS) return code;
  while (harness->calcAttemptCount() == 0 && harness->pendingControlCount(NestedHistoryHarness::kRealtimeSession) > 0) {
    code = harness->dispatchQueuedControl(NestedHistoryHarness::kRealtimeSession);
    if (code != TSDB_CODE_SUCCESS) return code;
  }
  return harness->calcAttemptCount() == 1 ? TSDB_CODE_SUCCESS : TSDB_CODE_INTERNAL_ERROR;
}

TEST_F(StreamNestedRecalcTest, DisappearedLineageDoesNotEmitNotice) {
  NestedHistoryHarness harness;
  ASSERT_EQ(TSDB_CODE_SUCCESS, startTask14RealtimeIdentity(&harness, true));

  const PipelineCalcAttempt* initialAttempt = harness.calcAttempt(0);
  ASSERT_NE(nullptr, initialAttempt);
  ASSERT_EQ(TDMT_STREAM_TRIGGER_CALC, initialAttempt->msgType);
  ASSERT_FALSE(initialAttempt->serializedRequest.empty());
  const SSTriggerCalcRequest& initialRequest = initialAttempt->decoded;
  EXPECT_EQ(42, initialRequest.gid);
  EXPECT_EQ(1, initialRequest.sessionId);
  EXPECT_EQ(STREAM_TRIGGER_COUNT, initialRequest.triggerType);
  ASSERT_NE(nullptr, initialRequest.params);
  ASSERT_EQ(1, taosArrayGetSize(initialRequest.params));
  const auto* initialParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(initialRequest.params, 0));
  ASSERT_NE(nullptr, initialParam);
  EXPECT_EQ(1000, initialParam->wstart);
  EXPECT_EQ(1000, initialParam->wend);
  EXPECT_EQ(0, initialParam->wduration);
  EXPECT_EQ(1, initialParam->wrownum);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_CLOSE, initialParam->notifyType);
  ASSERT_NE(nullptr, initialRequest.pAncestorContext);
  ASSERT_NE(nullptr, initialRequest.pAncestorContext->pParamContexts);
  ASSERT_EQ(1, taosArrayGetSize(initialRequest.pAncestorContext->pParamContexts));
  const auto* initialContext =
      static_cast<const SStreamAncestorParamContext*>(taosArrayGet(initialRequest.pAncestorContext->pParamContexts, 0));
  ASSERT_NE(nullptr, initialContext);
  EXPECT_EQ(0, initialContext->paramIndex);
  EXPECT_EQ(42, initialContext->leafIdentity.gid);
  EXPECT_EQ(WINDOW_TYPE_COUNT, initialContext->leafIdentity.triggerType);
  EXPECT_EQ(1000, initialContext->leafIdentity.openingTs);
  EXPECT_EQ(0, initialContext->leafIdentity.nativeDiscriminator);
  ASSERT_NE(nullptr, initialContext->leafIdentity.lineage.pScopes);
  ASSERT_EQ(1, taosArrayGetSize(initialContext->leafIdentity.lineage.pScopes));
  const auto* initialScope =
      static_cast<const SScopeInstanceId*>(taosArrayGet(initialContext->leafIdentity.lineage.pScopes, 0));
  ASSERT_NE(nullptr, initialScope);
  EXPECT_EQ(0, initialScope->layerIndex);
  EXPECT_EQ(WINDOW_TYPE_SESSION, initialScope->triggerType);
  EXPECT_EQ(1000, initialScope->openingTs);
  EXPECT_EQ(0, initialScope->nativeDiscriminator);
  ASSERT_NE(nullptr, initialContext->pSnapshots);
  ASSERT_EQ(1, taosArrayGetSize(initialContext->pSnapshots));
  const auto* initialSnapshot =
      static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(initialContext->pSnapshots, 0));
  ASSERT_NE(nullptr, initialSnapshot);
  EXPECT_EQ(0, initialSnapshot->layerIndex);
  EXPECT_EQ(WINDOW_TYPE_SESSION, initialSnapshot->triggerType);
  EXPECT_EQ(0, initialSnapshot->placeholderMask);
  EXPECT_EQ(1000, initialSnapshot->values.window.start);
  EXPECT_EQ(1000, initialSnapshot->values.window.end);
  EXPECT_EQ(0, initialSnapshot->values.window.duration);
  EXPECT_EQ(1, initialSnapshot->values.window.rownum);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcAttempt(0));

  SSTriggerRealtimeGroup* recalcGroup = harness.realtimeGroup();
  ASSERT_NE(nullptr, recalcGroup);
  STimeWindow requested = {NestedHistoryHarness::kScanStart - 1, NestedHistoryHarness::kScanStart};
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAddRecalcRequest(harness.task(), recalcGroup, &requested, false, true, true, 0));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedHistoryStart());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs(NestedHistoryHarness::kScanStart - 1));
  STimeWindow replayRange = {};
  ASSERT_TRUE(harness.pendingMetaRange(&replayRange));
  EXPECT_LE(replayRange.skey, NestedHistoryHarness::kScanStart - 1);
  EXPECT_GE(replayRange.ekey, NestedHistoryHarness::kScanStart);
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondMetaAt(NestedHistoryHarness::kScanStart - 1, NestedHistoryHarness::kTableUid, 1));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({NestedHistoryHarness::kScanStart - 1}, {20}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
  ASSERT_EQ(2, harness.calcAttemptCount());

  const PipelineCalcAttempt* replayAttempt = harness.calcAttempt(1);
  ASSERT_NE(nullptr, replayAttempt);
  ASSERT_EQ(TDMT_STREAM_TRIGGER_CALC, replayAttempt->msgType);
  ASSERT_FALSE(replayAttempt->serializedRequest.empty());
  const SSTriggerCalcRequest& replayRequest = replayAttempt->decoded;
  EXPECT_EQ(42, replayRequest.gid);
  EXPECT_EQ(2, replayRequest.sessionId);
  EXPECT_EQ(STREAM_TRIGGER_COUNT, replayRequest.triggerType);
  EXPECT_FALSE(replayRequest.isMultiGroupCalc);
  ASSERT_NE(nullptr, replayRequest.params);
  ASSERT_EQ(1, taosArrayGetSize(replayRequest.params));
  const auto* replayParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(replayRequest.params, 0));
  ASSERT_NE(nullptr, replayParam);
  EXPECT_EQ(999, replayParam->wstart);
  EXPECT_EQ(999, replayParam->wend);
  EXPECT_EQ(0, replayParam->wduration);
  EXPECT_EQ(1, replayParam->wrownum);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, replayParam->notifyType);
  ASSERT_NE(nullptr, replayRequest.pContextPolicy);
  ASSERT_NE(nullptr, replayRequest.pContextPolicy->pEntries);
  ASSERT_EQ(1, taosArrayGetSize(replayRequest.pContextPolicy->pEntries));
  const auto* replayPolicy =
      static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(replayRequest.pContextPolicy->pEntries, 0));
  ASSERT_NE(nullptr, replayPolicy);
  EXPECT_EQ(42, replayPolicy->gid);
  EXPECT_EQ(0, replayPolicy->paramIndex);
  EXPECT_EQ(STREAM_CONTEXT_POLICY_ANCESTOR, replayPolicy->contextPolicy);
  ASSERT_NE(nullptr, replayRequest.pAncestorContext);
  ASSERT_NE(nullptr, replayRequest.pAncestorContext->pParamContexts);
  ASSERT_EQ(1, taosArrayGetSize(replayRequest.pAncestorContext->pParamContexts));
  EXPECT_EQ(nullptr, replayRequest.pAncestorContext->pReadScopeBindings);
  const auto* replayContext =
      static_cast<const SStreamAncestorParamContext*>(taosArrayGet(replayRequest.pAncestorContext->pParamContexts, 0));
  ASSERT_NE(nullptr, replayContext);
  EXPECT_EQ(0, replayContext->paramIndex);
  EXPECT_EQ(42, replayContext->leafIdentity.gid);
  EXPECT_EQ(WINDOW_TYPE_COUNT, replayContext->leafIdentity.triggerType);
  EXPECT_EQ(999, replayContext->leafIdentity.openingTs);
  EXPECT_EQ(0, replayContext->leafIdentity.nativeDiscriminator);
  ASSERT_NE(nullptr, replayContext->leafIdentity.lineage.pScopes);
  ASSERT_EQ(1, taosArrayGetSize(replayContext->leafIdentity.lineage.pScopes));
  const auto* replayScope =
      static_cast<const SScopeInstanceId*>(taosArrayGet(replayContext->leafIdentity.lineage.pScopes, 0));
  ASSERT_NE(nullptr, replayScope);
  EXPECT_EQ(0, replayScope->layerIndex);
  EXPECT_EQ(WINDOW_TYPE_SESSION, replayScope->triggerType);
  EXPECT_EQ(999, replayScope->openingTs);
  EXPECT_EQ(0, replayScope->nativeDiscriminator);
  ASSERT_NE(nullptr, replayContext->pSnapshots);
  ASSERT_EQ(1, taosArrayGetSize(replayContext->pSnapshots));
  const auto* replaySnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(replayContext->pSnapshots, 0));
  ASSERT_NE(nullptr, replaySnapshot);
  EXPECT_EQ(0, replaySnapshot->layerIndex);
  EXPECT_EQ(WINDOW_TYPE_SESSION, replaySnapshot->triggerType);
  EXPECT_EQ(0, replaySnapshot->placeholderMask);
  EXPECT_EQ(999, replaySnapshot->values.window.start);
  EXPECT_EQ(999, replaySnapshot->values.window.end);
  EXPECT_EQ(0, replaySnapshot->values.window.duration);
  EXPECT_EQ(1, replaySnapshot->values.window.rownum);
  EXPECT_EQ((std::vector<int32_t>{TDMT_STREAM_TRIGGER_CALC, TDMT_STREAM_TRIGGER_CALC}),
            harness.runnerMutationMsgTypes());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcAttempt(1));

  EXPECT_TRUE(gNestedOutboxPayloads.empty());
}

static void configureTask14RecalcFixture(CountRecalcFixture* fixture) {
  fixture->task_.addOptions = STREAM_OPTION_NESTED_WINDOW_PLAN;
  fixture->task_.pWindowPlan = makeDeploySessionPlan(false);
  ASSERT_NE(nullptr, fixture->task_.pWindowPlan);
  auto* root = static_cast<SStreamWindowLayerSpec*>(taosArrayGet(fixture->task_.pWindowPlan->pLayers, 0));
  ASSERT_NE(nullptr, root);
  *root = {};
  root->triggerType = WINDOW_TYPE_INTERVAL;
  root->trigger.sliding.intervalUnit = TIME_UNIT_MILLISECOND;
  root->trigger.sliding.slidingUnit = TIME_UNIT_MILLISECOND;
  root->trigger.sliding.offsetUnit = TIME_UNIT_MILLISECOND;
  root->trigger.sliding.soffsetUnit = TIME_UNIT_MILLISECOND;
  root->trigger.sliding.precision = TSDB_TIME_PRECISION_MILLI;
  root->trigger.sliding.interval = 100;
  root->trigger.sliding.sliding = 100;
  const TSKEY cutoff = 0;
  ASSERT_EQ(TSDB_CODE_SUCCESS, tSimpleHashPut(fixture->task_.pHistoryCutoffTime, &fixture->group_.gid,
                                              sizeof(fixture->group_.gid), &cutoff, sizeof(cutoff)));
}

static void destroyTask14RecalcFixture(CountRecalcFixture* fixture) {
  tDestroyStreamWindowPlan(&fixture->task_.pWindowPlan);
}

static void expectMergedRequestCovers(CountRecalcFixture* fixture, SSTriggerRecalcRequest* request,
                                      STimeWindow firstRange, STimeWindow secondRange) {
  ASSERT_NE(nullptr, request);
  ASSERT_NE(nullptr, request->impactDomain.pRootExtents);
  for (const STimeWindow range : {firstRange, secondRange}) {
    SRecalcImpactDomain child = {};
    ASSERT_EQ(TSDB_CODE_SUCCESS, stWindowChainBuildRecalcImpactDomain(fixture->task_.pWindowPlan, fixture->group_.gid,
                                                                      &request->scanRange, &range, &child));
    EXPECT_EQ(child.gid, request->impactDomain.gid);
    EXPECT_GE(child.replayAnchor, request->impactDomain.replayAnchor);
    EXPECT_LE(child.capturedFrontier, request->impactDomain.capturedFrontier);
    for (int32_t childIndex = 0; childIndex < taosArrayGetSize(child.pRootExtents); ++childIndex) {
      const auto* pChild = static_cast<const STimeWindow*>(taosArrayGet(child.pRootExtents, childIndex));
      ASSERT_NE(nullptr, pChild);
      bool covered = false;
      for (int32_t mergedIndex = 0; mergedIndex < taosArrayGetSize(request->impactDomain.pRootExtents); ++mergedIndex) {
        const auto* pMerged =
            static_cast<const STimeWindow*>(taosArrayGet(request->impactDomain.pRootExtents, mergedIndex));
        ASSERT_NE(nullptr, pMerged);
        if (pMerged->skey <= pChild->skey && pMerged->ekey >= pChild->ekey) {
          covered = true;
          break;
        }
      }
      EXPECT_TRUE(covered);
    }
    stDestroyRecalcImpactDomain(&child);
  }
}

TEST_F(StreamNestedRecalcTest, ReadyMergeUnionsImpactDomains) {
  CountRecalcFixture fixture;
  configureTask14RecalcFixture(&fixture);
  const STimeWindow first = {100, 109};
  const STimeWindow second = {300, 309};
  STimeWindow requested = first;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAddRecalcRequest(&fixture.task_, &fixture.group_, &requested, false, true, true, 0));
  requested = second;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAddRecalcRequest(&fixture.task_, &fixture.group_, &requested, false, true, true, 0));
  SSTriggerRecalcRequest* merged = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskFetchRecalcRequest(&fixture.task_, &merged));
  expectMergedRequestCovers(&fixture, merged, first, second);
  stTriggerTaskDestroyRecalcRequest(&merged);
  destroyTask14RecalcFixture(&fixture);
}

TEST_F(StreamNestedRecalcTest, PendingMergeUnionsImpactDomains) {
  CountRecalcFixture fixture;
  configureTask14RecalcFixture(&fixture);
  fixture.group_.oldThreshold = 50;
  fixture.group_.newThreshold = 400;
  const STimeWindow later = {300, 309};
  const STimeWindow earlier = {100, 109};
  STimeWindow requested = later;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAddRecalcRequest(&fixture.task_, &fixture.group_, &requested, false, false, true, 0));
  requested = earlier;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAddRecalcRequest(&fixture.task_, &fixture.group_, &requested, false, false, true, 0));
  auto* pendingOwners = static_cast<SSTriggerGroupPendingRecalc*>(
      tSimpleHashGet(fixture.task_.pGroupPendingRecalcs, &fixture.group_.gid, sizeof(fixture.group_.gid)));
  ASSERT_NE(nullptr, pendingOwners);
  EXPECT_EQ(1, TD_DLIST_NELES(&pendingOwners->pendingRequests));
  fixture.group_.oldThreshold = 500;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskReadyRecalcRequest(&fixture.task_, &fixture.group_));
  SSTriggerRecalcRequest* merged = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskFetchRecalcRequest(&fixture.task_, &merged));
  expectMergedRequestCovers(&fixture, merged, earlier, later);
  stTriggerTaskDestroyRecalcRequest(&merged);
  EXPECT_EQ(0, TD_DLIST_NELES(&pendingOwners->pendingRequests));
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskFetchRecalcRequest(&fixture.task_, &merged));
  EXPECT_EQ(nullptr, merged);
  destroyTask14RecalcFixture(&fixture);
}

